package main

import (
	"io"
	"strconv"
	"strings"
)

// renderer mimics the behaviour of a line-based terminal renderer that only
// repaints the lines that changed since the previous frame.
type renderer struct {
	out           io.Writer
	width, height int
	lastRender    string
	lastLines     []string
	linesRendered int
	altScreen     bool
	cursorHidden  bool
	buf           string
	hasBuf        bool
}

func newRenderer(out io.Writer) *renderer {
	return &renderer{out: out}
}

func (r *renderer) execute(s string) {
	io.WriteString(r.out, s)
}

func (r *renderer) write(view string) {
	if view == "" {
		view = " "
	}
	r.buf = view
	r.hasBuf = true
}

// repaint forces the whole frame to be redrawn on the next flush.
func (r *renderer) repaint() {
	r.lastRender = ""
	r.lastLines = nil
}

func (r *renderer) setSize(w, h int) {
	r.width = w
	r.height = h
	r.repaint()
}

func (r *renderer) hideCursor() {
	r.cursorHidden = true
	r.execute("\x1b[?25l")
}

func (r *renderer) showCursor() {
	r.cursorHidden = false
	r.execute("\x1b[?25h")
}

func (r *renderer) enterAltScreen() {
	if r.altScreen {
		return
	}
	r.altScreen = true
	r.execute("\x1b[?1049h")
	r.execute("\x1b[2J")
	r.execute("\x1b[H")
	if r.cursorHidden {
