package main

import (
	"strings"
)

// escapeLen returns the length in bytes of the escape sequence starting at
// s[i] (s[i] == 0x1b). If the sequence is incomplete the remainder of the
// string is consumed.
func escapeLen(s string, i int) int {
	n := len(s)
	if i+1 >= n {
		return n - i
	}
	switch s[i+1] {
	case '[':
		// CSI: parameters 0x30-0x3f, intermediates 0x20-0x2f, final 0x40-0x7e
		j := i + 2
		for j < n {
			c := s[j]
			if c >= 0x40 && c <= 0x7e {
				return j + 1 - i
			}
			j++
		}
		return n - i
	case ']', 'P', '^', '_', 'X':
		// OSC / DCS / PM / APC / SOS: terminated by BEL or ST (ESC \)
		j := i + 2
		for j < n {
			if s[j] == 0x07 {
				return j + 1 - i
			}
			if s[j] == 0x1b && j+1 < n && s[j+1] == '\\' {
				return j + 2 - i
			}
			j++
		}
		return n - i
	default:
		// two byte escape
		return 2
	}
}

// stringWidth returns the display width of s ignoring ANSI escape sequences.
func stringWidth(s string) int {
	w := 0
	for i := 0; i < len(s); {
		if s[i] == 0x1b {
			i += escapeLen(s, i)
			continue
		}
		r, size := decodeRune(s[i:])
		w += runeWidth(r)
		i += size
	}
	return w
}

func decodeRune(s string) (rune, int) {
	for _, r := range s {
		size := len(string(r))
		if r == 0xfffd && size == 3 && !(len(s) >= 3 && s[0] == 0xef && s[1] == 0xbf && s[2] == 0xbd) {
			return r, 1
		}
		return r, size
	}
	return 0, 1
}

// ansiTruncate truncates s to the given width keeping escape sequences.
func ansiTruncate(s string, width int, tail string) string {
	if stringWidth(s) <= width {
		return s
	}
	width -= plainWidth(tail)
	if width < 0 {
		return ""
	}
	var b strings.Builder
	cur := 0
	ignoring := false
	for i := 0; i < len(s); {
		if s[i] == 0x1b {
			l := escapeLen(s, i)
			b.WriteString(s[i : i+l])
			i += l
			continue
		}
		r, size := decodeRune(s[i:])
		rw := runeWidth(r)
		if r < 0x80 {
			// printable ASCII and control characters
			if cur >= width && !ignoring {
				ignoring = true
				b.WriteString(tail)
			}
			if ignoring {
				i += size
				continue
			}
			cur += rw
			b.WriteByte(s[i])
			i += size
			continue
		}
		cur += rw
		if ignoring {
			i += size
			continue
		}
		if cur > width {
			ignoring = true
			b.WriteString(tail)
			i += size
			continue
		}
		b.WriteString(s[i : i+size])
		i += size
	}
	return b.String()
}

// padRight pads s with spaces up to width cells.
func padRight(s string, width int) string {
	w := stringWidth(s)
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

// maxLineWidth returns the widest line of a multi-line string.
func maxLineWidth(lines []string) int {
	m := 0
	for _, l := range lines {
		if w := stringWidth(l); w > m {
			m = w
		}
	}
	return m
}

// joinVertical joins blocks vertically, left aligned, padding every line to
// the width of the widest line.
func joinVertical(blocks ...string) string {
	var lines []string
	for _, b := range blocks {
		lines = append(lines, strings.Split(b, "\n")...)
	}
	w := maxLineWidth(lines)
	for i := range lines {
		lines[i] = padRight(lines[i], w)
	}
	return strings.Join(lines, "\n")
}

// joinHorizontal joins blocks horizontally, top aligned.
func joinHorizontal(blocks ...string) string {
	if len(blocks) == 0 {
		return ""
	}
	if len(blocks) == 1 {
		return blocks[0]
	}
	var split [][]string
	maxHeight := 0
	for _, b := range blocks {
		ls := strings.Split(b, "\n")
		split = append(split, ls)
		if len(ls) > maxHeight {
			maxHeight = len(ls)
		}
	}
	widths := make([]int, len(blocks))
	for i, ls := range split {
		widths[i] = maxLineWidth(ls)
		for len(split[i]) < maxHeight {
			split[i] = append(split[i], "")
		}
	}
	var b strings.Builder
	for row := 0; row < maxHeight; row++ {
		for i := range split {
			b.WriteString(padRight(split[i][row], widths[i]))
		}
		if row < maxHeight-1 {
			b.WriteByte('\n')
		}
	}
	return b.String()
}

// roundedBox renders text inside a rounded border box with one cell of
// horizontal padding (lipgloss style).
func roundedBox(text string) string {
	lines := strings.Split(text, "\n")
	w := maxLineWidth(lines) + 2
	var b strings.Builder
	b.WriteString("╭" + strings.Repeat("─", w) + "╮\n")
	for _, l := range lines {
		b.WriteString("│ " + padRight(l, w-2) + " │\n")
	}
	b.WriteString("╰" + strings.Repeat("─", w) + "╯")
	return b.String()
}
