// parseColor converts a user supplied colour string into a terminal colour
// for the given profile. Returns kind colorNone when invalid.
func parseColor(p colorProfile, s string) termColor {
	if len(s) == 0 {
		return termColor{}
	}
	var c termColor
	if strings.HasPrefix(s, "#") {
		var ok bool
		c, ok = parseHex(s)
		if !ok {
			return termColor{}
		}
	} else {
		i, err := strconv.Atoi(s)
		if err != nil {
			return termColor{}
		}
		if i < 16 {
			c = termColor{kind: colorANSI, idx: i}
		} else {
			c = termColor{kind: colorANSI256, idx: i}
		}
	}
	return convertColor(p, c)
}

func convertColor(p colorProfile, c termColor) termColor {
	if p == profileAscii {
		return termColor{}
	}
	switch c.kind {
	case colorANSI:
		return c
	case colorANSI256:
		if p == profileANSI {
			return ansi256ToANSI(c.idx)
		}
		return c
	case colorRGB:
		if p != profileTrueColor {
			ac := rgbToANSI256(c)
			if p == profileANSI {
				return ansi256ToANSI(ac.idx)
			}
			return ac
		}
		return c
	}
	return c
}

func (c termColor) sequence(bg bool) string {
	switch c.kind {
	case colorANSI:
		if bg {
			if c.idx < 8 {
				return strconv.Itoa(40 + c.idx)
			}
			return strconv.Itoa(100 + c.idx - 8)
		}
		if c.idx < 8 {
			return strconv.Itoa(30 + c.idx)
		}
		return strconv.Itoa(90 + c.idx - 8)
	case colorANSI256:
		if bg {
			return fmt.Sprintf("48;5;%d", c.idx)
		}
		return fmt.Sprintf("38;5;%d", c.idx)
	case colorRGB:
		prefix := "38"
		if bg {
			prefix = "48"
		}
		return fmt.Sprintf("%s;2;%d;%d;%d", prefix, uint8(c.r*255), uint8(c.g*255), uint8(c.b*255))
	}
	return ""
}

// ---- colour distance (HSLuv) ----

func linearize(v float64) float64 {
	if v <= 0.04045 {
		return v / 12.92
	}
	return math.Pow((v+0.055)/1.055, 2.4)
}

func (c termColor) xyz() (x, y, z float64) {
	r, g, b := linearize(c.r), linearize(c.g), linearize(c.b)
	x = 0.4124564*r + 0.3575761*g + 0.1804375*b
	y = 0.2126729*r + 0.7151522*g + 0.0721750*b
	z = 0.0193339*r + 0.1191920*g + 0.9503041*b
	return
}

var hsluvD65 = [3]float64{0.95045592705167, 1.0, 1.089057750759878}

func xyzToUV(x, y, z float64) (u, v float64) {
	denom := x + 15.0*y + 3.0*z
	if denom == 0.0 {
		return 0, 0
	}
	return 4.0 * x / denom, 9.0 * y / denom
}

func xyzToLuvWhiteRef(x, y, z float64, wref [3]float64) (l, u, v float64) {
	if y/wref[1] <= 6.0/29.0*6.0/29.0*6.0/29.0 {
		l = y / wref[1] * (29.0 / 3.0 * 29.0 / 3.0 * 29.0 / 3.0) / 100.0
	} else {
		l = 1.16*math.Cbrt(y/wref[1]) - 0.16
	}
	ubis, vbis := xyzToUV(x, y, z)
	un, vn := xyzToUV(wref[0], wref[1], wref[2])
	u = 13.0 * l * (ubis - un)
	v = 13.0 * l * (vbis - vn)
	return
}

var hsluvM = [3][3]float64{
	{3.2409699419045214, -1.5373831775700935, -0.49861076029300328},
	{-0.96924363628087983, 1.8759675015077207, 0.041555057407175613},
	{0.055630079696993609, -0.20397695888897657, 1.0569715142428786},
}

const (
	hsluvKappa   = 903.2962962962963
	hsluvEpsilon = 0.0088564516790356308
)

func hsluvGetBounds(l float64) [6][2]float64 {
	var sub2 float64
	var ret [6][2]float64
	sub1 := math.Pow(l+16.0, 3.0) / 1560896.0
	if sub1 > hsluvEpsilon {
		sub2 = sub1
	} else {
		sub2 = l / hsluvKappa
	}
	for i := range hsluvM {
		for k := 0; k < 2; k++ {
			top1 := (284517.0*hsluvM[i][0] - 94839.0*hsluvM[i][2]) * sub2
			top2 := (838422.0*hsluvM[i][2]+769860.0*hsluvM[i][1]+731718.0*hsluvM[i][0])*l*sub2 - 769860.0*float64(k)*l
			bottom := (632260.0*hsluvM[i][2]-126452.0*hsluvM[i][1])*sub2 + 126452.0*float64(k)
			ret[i*2+k][0] = top1 / bottom
			ret[i*2+k][1] = top2 / bottom
		}
	}
	return ret
}

func hsluvMaxChromaForLH(l, h float64) float64 {
	hrad := h / 360.0 * math.Pi * 2.0
	minLength := math.MaxFloat64
	for _, line := range hsluvGetBounds(l) {
		length := line[1] / (math.Sin(hrad) - line[0]*math.Cos(hrad))
		if length > 0.0 && length < minLength {
			minLength = length
		}
	}
	return minLength
}

func clamp01(v float64) float64 {
	return math.Max(0.0, math.Min(v, 1.0))
}

// hsluv returns h in [0,360), s and l in [0,1].
func (c termColor) hsluv() (h, s, l float64) {
	x, y, z := c.xyz()
	L, u, v := xyzToLuvWhiteRef(x, y, z, hsluvD65)
	C := math.Sqrt(u*u + v*v)
	H := math.Mod(57.29577951308232087721*math.Atan2(v, u)+360.0, 360.0)
	// LuvLChToHSLuv
	C *= 100.0
	L *= 100.0
	var S float64
	if L > 99.9999999 || L < 0.00000001 {
		S = 0.0
	} else {
		max := hsluvMaxChromaForLH(L, H)
		S = C / max * 100.0
	}
	return H, clamp01(S / 100.0), clamp01(L / 100.0)
}

func sq(v float64) float64 { return v * v }

func distanceHSLuv(c1, c2 termColor) float64 {
	h1, s1, l1 := c1.hsluv()
	h2, s2, l2 := c2.hsluv()
	return math.Sqrt(sq((h1-h2)/100.0) + sq(s1-s2) + sq(l1-l2))
}

func rgbToANSI256(c termColor) termColor {
	v2ci := func(v float64) int {
		if v < 48 {
			return 0
		}
		if v < 115 {
			return 1
		}
		return int((v - 35) / 40)
	}
	r := v2ci(c.r * 255.0)
	g := v2ci(c.g * 255.0)
	b := v2ci(c.b * 255.0)
	ci := 36*r + 6*g + b
	i2cv := [6]int{0, 0x5f, 0x87, 0xaf, 0xd7, 0xff}
	cr := i2cv[r]
	cg := i2cv[g]
	cb := i2cv[b]
	var grayIdx int
	average := (r + g + b) / 3
	if average > 238 {
		grayIdx = 23
	} else {
		grayIdx = (average - 3) / 10
	}
	gv := 8 + 10*grayIdx
	c2 := termColor{kind: colorRGB, r: float64(cr) / 255.0, g: float64(cg) / 255.0, b: float64(cb) / 255.0}
	g2 := termColor{kind: colorRGB, r: float64(gv) / 255.0, g: float64(gv) / 255.0, b: float64(gv) / 255.0}
	colorDist := distanceHSLuv(c, c2)
	grayDist := distanceHSLuv(c, g2)
	if colorDist <= grayDist {
		return termColor{kind: colorANSI256, idx: 16 + ci}
	}
	return termColor{kind: colorANSI256, idx: 232 + grayIdx}
}

var ansiBaseHex = [16]string{
	"#000000", "#800000", "#008000", "#808000", "#000080", "#800080", "#008080", "#c0c0c0",
	"#808080", "#ff0000", "#00ff00", "#ffff00", "#0000ff", "#ff00ff", "#00ffff", "#ffffff",
}

func ansi256Hex(i int) string {
	if i < 0 || i > 255 {
		return "#000000"
	}
	if i < 16 {
		return ansiBaseHex[i]
	}
	if i < 232 {
		i -= 16
		levels := [6]int{0, 0x5f, 0x87, 0xaf, 0xd7, 0xff}
		r := levels[i/36]
		g := levels[(i%36)/6]
		b := levels[i%6]
		return fmt.Sprintf("#%02x%02x%02x", r, g, b)
	}
	v := 8 + 10*(i-232)
	return fmt.Sprintf("#%02x%02x%02x", v, v, v)
}

func ansi256ToANSI(idx int) termColor {
	var r int
	md := math.MaxFloat64
	h, _ := parseHex(ansi256Hex(idx))
	for i := 0; i <= 15; i++ {
		hb, _ := parseHex(ansiBaseHex[i])
		d := distanceHSLuv(h, hb)
		if d < md {
			md = d
			r = i
		}
	}
	return termColor{kind: colorANSI, idx: r}
}

// ---- styles ----

type style struct {
	fg, bg      termColor
	bold        bool
	italic      bool
	profile     colorProfile
}

func (s style) render(text string) string {
	if s.profile == profileAscii {
		return text
	}
	var params []string
	if s.bold {
		params = append(params, "1")
	}
	if s.italic {
		params = append(params, "3")
	}
	if s.fg.kind != colorNone {
		params = append(params, s.fg.sequence(false))
	}
	if s.bg.kind != colorNone {
		params = append(params, s.bg.sequence(true))
	}
	if len(params) == 0 {
		return text
	}
	return "\x1b[" + strings.Join(params, ";") + "m" + text + "\x1b[0m"
}
EOF
