}

var unknownCSIRe = regexp.MustCompile(`^\x1b\[[\x30-\x3f]*[\x20-\x2f]*[\x40-\x7e]`)

// detectSequence tries to match a known escape sequence or control key at
// the start of b.
func detectSequence(b []byte) (bool, int, keyMsg) {
	for i := len(b); i > 0; i-- {
		if i > 12 {
			continue
		}
		s := string(b[:i])
		if name, ok := keySequences[s]; ok {
			return true, i, keyMsg{name: name}
		}
		// alt + sequence
		if len(s) > 1 && s[0] == 0x1b {
			if name, ok := keySequences[s[1:]]; ok {
				return true, i, keyMsg{name: name, alt: true}
			}
		}
	}
	if len(b) > 0 {
		if name, ok := controlNames[b[0]]; ok {
			return true, 1, keyMsg{name: name}
		}
		if b[0] == ' ' {
			return true, 1, keyMsg{name: " ", runes: []rune{' '}}
		}
		if b[0] == 0x1b && len(b) > 1 {
			if name, ok := controlNames[b[1]]; ok {
				return true, 2, keyMsg{name: name, alt: true}
			}
			if b[1] == ' ' {
				return true, 2, keyMsg{name: " ", runes: []rune{' '}, alt: true}
			}
		}
	}
	if loc := unknownCSIRe.FindIndex(b); loc != nil {
		return true, loc[1], keyMsg{name: "unknown"}
	}
	return false, 0, keyMsg{}
}

// detectOneMsg parses one key message from b. Returns the number of bytes
// consumed (0 means more data is needed).
func detectOneMsg(b []byte, canHaveMoreData bool) (int, *keyMsg) {
	if bytes.HasPrefix(b, []byte("\x1b[200~")) {
		rest := b[6:]
		idx := bytes.Index(rest, []byte("\x1b[201~"))
		if idx < 0 {
			if canHaveMoreData {
				return 0, nil
			}
			idx = len(rest)
			content := rest[:idx]
			return 6 + idx, &keyMsg{name: string(content), runes: []rune(string(content)), paste: true}
		}
		content := rest[:idx]
		return 6 + idx + 6, &keyMsg{name: string(content), runes: []rune(string(content)), paste: true}
	}
	if ok, w, k := detectSequence(b); ok {
		return w, &k
	}
	alt := false
	i := 0
	if b[0] == 0x1b {
		alt = true
		i++
	}
	var runes []rune
	for rw := 0; i < len(b); i += rw {
		var r rune
		r, rw = utf8.DecodeRune(b[i:])
		if r == utf8.RuneError || r <= 0x1f || r == 0x7f || r == ' ' {
			break
		}
		runes = append(runes, r)
		if alt {
			i += rw
			break
		}
	}
	if i >= len(b) && canHaveMoreData {
		return 0, nil
	}
	if len(runes) > 0 {
		return i, &keyMsg{name: string(runes), runes: runes, alt: alt}
	}
	if alt && len(b) == 1 {
		return 1, &keyMsg{name: "esc"}
	}
	return 1, &keyMsg{name: "unknown"}
}

// parseKeys splits a chunk of input into key messages. Leftover bytes that
// may be incomplete are returned.
func parseKeys(b []byte, canHaveMoreData bool) ([]keyMsg, []byte) {
	var msgs []keyMsg
	for i := 0; i < len(b); {
		w, k := detectOneMsg(b[i:], canHaveMoreData)
		if w == 0 {
			return msgs, append([]byte(nil), b[i:]...)
		}
		if k != nil {
			msgs = append(msgs, *k)
		}
		i += w
	}
	return msgs, nil
}
