	path := filepath.Join(m.path, f.Name())
	if s, ok := m.previewCache[path]; ok {
		return s
	}
	s := m.buildPreview(path, f)
	m.previewCache[path] = s
	return s
}

func (m *model) buildPreview(path string, f fs.DirEntry) string {
	info, err := os.Stat(path)
	if err != nil {
		return roundedBox(err.Error())
	}
	if info.IsDir() {
		return m.dirPreview(path)
	}
	if isImageExt(f.Name()) {
		return m.imagePreview(path)
	}
	file, err := os.Open(path)
	if err != nil {
		return roundedBox(err.Error())
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, previewReadLimit))
	if err != nil {
