package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"os/exec"
	"os/signal"
	"path/filepath"
	"strings"
	"syscall"
	"time"
)

const version = "v1.13.0"

type program struct {
	m        *model
	r        *renderer
	in       *os.File // tty used for input
	out      *os.File // output (stderr)
	inState  *termState
	keys     chan []keyMsg
	events   chan func()
	readStop chan struct{}
	readDone chan struct{}
}

func main() {
	startPath := ""
	m := newModel("")
	for _, arg := range os.Args[1:] {
		switch arg {
		case "--help", "-h":
			fmt.Fprint(os.Stderr, usage())
			os.Exit(1)
		case "--version", "-v":
			fmt.Println(version)
			os.Exit(0)
		case "--icons":
			m.showIcons = true
		case "--dir-only":
			m.dirOnly = true
		case "--hide-hidden":
			m.hideHidden = true
		case "--preview":
			m.previewOn = true
		case "--with-border":
			m.withBorder = true
		case "--fuzzy":
			m.fuzzyMode = true
		default:
			if startPath == "" {
				startPath = arg
			}
		}
	}

	if sb, ok := os.LookupEnv("WALK_STATUS_BAR"); ok && sb != "" {
		m.statusBar = compileStatusBar(sb)
	}

	var err error
	if startPath == "" {
		startPath, err = os.Getwd()
		if err != nil {
			panic(err)
		}
	} else {
		startPath, err = filepath.Abs(startPath)
		if err != nil {
			panic(err)
		}
	}
	m.path = startPath

	p := &program{m: m, out: os.Stderr}
	code := p.run()
	os.Exit(code)
}

func (p *program) run() int {
	// Input: stdin if it is a terminal, otherwise /dev/tty.
	if isTerminal(os.Stdin.Fd()) {
		p.in = os.Stdin
	} else {
		f, err := openTTY()
		if err != nil {
			panic(fmt.Errorf("could not open a new TTY: %w", err))
		}
		p.in = f
	}

	outIsTTY := isTerminal(p.out.Fd())
	p.m.initStyles(detectProfile(outIsTTY))

	st, err := makeRaw(p.in.Fd())
	if err == nil {
		p.inState = st
	}
	defer restoreTerm(p.in.Fd(), p.inState)

	p.r = newRenderer(p.out)
	w, h, _ := getWinSize(p.out.Fd())
	p.r.width, p.r.height = w, h
	p.m.width, p.m.height = w, h

	// Query the terminal background colour (as the colour libraries do) and
	// wait for the reply.
	if outIsTTY {
		p.queryBackground()
	}

	p.r.hideCursor()
	p.r.execute("\x1b[?2004h")

	p.m.list()
	p.m.restorePosition()
	if p.m.previewOn {
		p.r.enterAltScreen()
	}

