package main

import (
	"sort"
	"unicode"
	"unicode/utf8"
)

type fuzzyMatch struct {
	Str            string
	Index          int
	MatchedIndexes []int
	Score          int
}

type fuzzyMatches []fuzzyMatch

func (a fuzzyMatches) Len() int           { return len(a) }
func (a fuzzyMatches) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a fuzzyMatches) Less(i, j int) bool { return a[i].Score >= a[j].Score }

const (
	firstCharMatchBonus            = 10
	matchFollowingSeparatorBonus   = 20
	camelCaseMatchBonus            = 20
	adjacentMatchBonus             = 5
	unmatchedLeadingCharPenalty    = -5
	maxUnmatchedLeadingCharPenalty = -15
)

var fuzzySeparators = []rune("/-_ .\\")

func isSeparator(r rune) bool {
	for _, s := range fuzzySeparators {
		if r == s {
			return true
		}
	}
	return false
}

func equalFold(tr, sr rune) bool {
	if tr == sr {
		return true
	}
	if tr < sr {
		tr, sr = sr, tr
	}
	if tr < utf8.RuneSelf && sr < utf8.RuneSelf {
		if 'A' <= sr && sr <= 'Z' && tr == sr+'a'-'A' {
			return true
		}
		return false
