package main

import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

func (p *program) handleKey(k keyMsg) {
	m := p.m
	name := k.String()
	typing := m.fuzzyMode || m.searchMode

	// keys that always work
	switch name {
	case "ctrl+c":
		m.exitCode = 2
		m.quitting = true
		return
	case "esc":
		m.exitCode = 0
		m.quitting = true
		return
	case "enter":
		p.open()
		return
	case "backspace":
		if m.searchMode || (m.fuzzyMode && m.search != "") {
			if m.search != "" {
				runes := []rune(m.search)
				m.search = string(runes[:len(runes)-1])
				if m.fuzzyMode && m.search == "" {
					m.searchMode = false
				}
				m.updateSearch()
			} else {
				m.searchMode = false
			}
		} else {
			m.goUp()
		}
		m.deleteCurrent = false
		return
	case " ":
		m.previewOn = !m.previewOn
		if m.previewOn {
			p.r.enterAltScreen()
		} else {
			p.r.exitAltScreen()
		}
		m.updateLayout()
		m.updateOffset()
		m.deleteCurrent = false
		return
	case "up", "down", "left", "right", "shift+up", "shift+down", "shift+left", "shift+right",
		"home", "end", "pgup", "pgdown":
		m.move(name)
		m.deleteCurrent = false
		return
	case "delete":
		p.deleteKey()
		return
	}

	if !m.fuzzyMode && name == "/" {
		m.searchMode = !m.searchMode
		m.search = ""
		m.deleteCurrent = false
		return
	}

	if typing {
		if len(k.runes) > 0 && !k.alt {
			m.search += string(k.runes)
			if m.fuzzyMode {
				m.searchMode = true
			}
			m.updateSearch()
		}
		m.deleteCurrent = false
		return
	}

	switch name {
	case "q":
		m.exitCode = 0
		m.quitting = true
	case "k":
		m.move("up")
	case "j":
		m.move("down")
	case "h":
		m.move("left")
	case "l":
		m.move("right")
	case "d":
		p.deleteKey()
		return
	case "u":
		p.undoDelete()
	case "y":
		p.yank()
	case ".":
		m.hideHidden = !m.hideHidden
		m.applyFilters()
		m.updateOffset()
	case "?":
		m.showHelp = !m.showHelp
	}
	m.deleteCurrent = false
}

func (m *model) move(name string) {
	if len(m.files) == 0 {
		return
	}
	switch name {
	case "up":
		m.moveUp()
	case "down":
		m.moveDown()
	case "left":
		m.moveLeft()
	case "right":
		m.moveRight()
	case "shift+up", "pgup":
		m.moveTop()
	case "shift+down", "pgdown":
		m.moveBottom()
	case "shift+left":
		m.moveLeftmost()
	case "shift+right":
		m.moveRightmost()
	case "home":
		m.moveStart()
	case "end":
		m.moveEnd()
	}
	m.updateOffset()
}

// updateSearch moves the cursor to the best fuzzy match.
func (m *model) updateSearch() {
	if m.search == "" {
		return
	}
	names := make([]string, len(m.files))
	for i, f := range m.files {
		names[i] = f.Name()
	}
	matches := fuzzyFind(m.search, names)
	if len(matches) == 0 {
		return
	}
	idx := matches[0].Index
	if m.rows > 0 {
		m.c = idx / m.rows
		m.r = idx % m.rows
	}
	m.updateOffset()
}

func (p *program) open() {
	m := p.m
	f := m.currentFile()
	if f == nil {
		return
	}
	path := filepath.Join(m.path, f.Name())
	info, err := os.Stat(path)
	if err != nil {
		panic(err)
	}
	m.searchMode = false
	m.search = ""
	m.deleteCurrent = false
	if info.IsDir() {
		m.enterDir(f.Name())
		return
	}
	// open file
	var cmd *exec.Cmd
	ext := strings.TrimPrefix(filepath.Ext(f.Name()), ".")
	if openWith := os.Getenv("WALK_OPEN_WITH"); openWith != "" {
		for _, pair := range strings.Split(openWith, ";") {
			kv := strings.SplitN(pair, ":", 2)
			if len(kv) != 2 {
				continue
			}
			if kv[0] == ext {
				parts := strings.Fields(kv[1])
				if len(parts) > 0 {
					args := append(parts[1:], path)
					cmd = exec.Command(parts[0], args...)
				}
				break
			}
		}
	}
	if cmd == nil {
		editor := os.Getenv("WALK_EDITOR")
		if editor == "" {
			editor = os.Getenv("EDITOR")
		}
		if editor == "" {
			editor = "less"
		}
		parts := strings.Fields(editor)
		if len(parts) == 0 {
			parts = []string{"less"}
		}
		args := append(parts[1:], path)
		cmd = exec.Command(parts[0], args...)
	}
	p.execProcess(cmd)
}

func (p *program) deleteKey() {
	m := p.m
	f := m.currentFile()
	if f == nil {
		m.deleteCurrent = false
		return
	}
	if !m.deleteCurrent {
		m.deleteCurrent = true
		return
	}
	m.deleteCurrent = false
	path := filepath.Join(m.path, f.Name())
	d := &pendingDelete{path: path, entry: f, left: 5, done: make(chan struct{})}
	m.toDelete = append(m.toDelete, d)
	m.applyFilters()
	m.updateOffset()
	go func() {
		t := time.NewTicker(time.Second)
		defer t.Stop()
		for {
			select {
			case <-d.done:
				return
			case <-t.C:
				p.events <- func() {
					if d.left > 0 {
						d.left--
						return
					}
					p.finishDelete(d)
				}
			}
		}
	}()
}

func (p *program) finishDelete(d *pendingDelete) {
	m := p.m
	// still pending?
	idx := -1
	for i, x := range m.toDelete {
		if x == d {
			idx = i
		}
	}
	if idx < 0 {
		return
	}
	close(d.done)
	m.toDelete = append(m.toDelete[:idx], m.toDelete[idx+1:]...)
	if cmd := os.Getenv("WALK_REMOVE_CMD"); cmd != "" {
		c := exec.Command(cmd, d.path)
		_ = c.Run()
	} else {
		_ = os.RemoveAll(d.path)
	}
	m.list()
	m.updateOffset()
}

func (p *program) undoDelete() {
	m := p.m
	if len(m.toDelete) == 0 {
		return
	}
	d := m.toDelete[len(m.toDelete)-1]
	close(d.done)
	m.toDelete = m.toDelete[:len(m.toDelete)-1]
	m.list()
	m.updateOffset()
}

func (p *program) yank() {
	m := p.m
	f := m.currentFile()
	if f == nil {
		return
	}
	path := filepath.Join(m.path, f.Name())
	copyToClipboard(path)
}

// copyToClipboard mimics the behaviour of the common clipboard helpers on
// Linux: wl-copy (when on Wayland), xclip, xsel, termux-clipboard-set.
func copyToClipboard(text string) {
	var args []string
	if os.Getenv("WAYLAND_DISPLAY") != "" {
		if _, err := exec.LookPath("wl-copy"); err == nil {
			if _, err := exec.LookPath("wl-paste"); err == nil {
				args = []string{"wl-copy"}
			}
		}
	}
	if args == nil {
		if _, err := exec.LookPath("xclip"); err == nil {
			args = []string{"xclip", "-in", "-selection", "clipboard"}
		} else if _, err := exec.LookPath("xsel"); err == nil {
			args = []string{"xsel", "--input", "--clipboard"}
		} else if _, err := exec.LookPath("termux-clipboard-set"); err == nil {
			args = []string{"termux-clipboard-set"}
		}
	}
	if args == nil {
		return
	}
	cmd := exec.Command(args[0], args[1:]...)
	cmd.Stdin = strings.NewReader(text)
	_ = cmd.Run()
}
