// Package expr implements a small expression language used for the status
// bar. The syntax follows the common "expr" style: pipes, member access,
// method calls, array/map literals and a set of builtin functions.
package expr

import (
	"fmt"
	"strings"
	"unicode"
	"unicode/utf8"
)

type tokenKind int

const (
	tokIdentifier tokenKind = iota
	tokNumber
	tokString
	tokOperator
	tokBracket
	tokEOF
)

func (k tokenKind) String() string {
	switch k {
	case tokIdentifier:
		return "Identifier"
	case tokNumber:
		return "Number"
	case tokString:
		return "String"
	case tokOperator:
		return "Operator"
	case tokBracket:
		return "Bracket"
	case tokEOF:
		return "EOF"
	}
	return "?"
}

type token struct {
	kind  tokenKind
	value string
	from  int // byte offset
	to    int
}

func (t token) String() string {
	if t.value == "" {
		return t.kind.String()
	}
	return fmt.Sprintf("%s(%q)", t.kind, t.value)
}

func (t token) is(kind tokenKind, values ...string) bool {
	if t.kind != kind {
		return false
	}
	if len(values) == 0 {
		return true
	}
	for _, v := range values {
		if t.value == v {
			return true
		}
	}
	return false
}

// Error is an error with a source location, formatted with a snippet.
type Error struct {
	Message string
	From    int
	Source  string
}

func (e *Error) Error() string {
	line, col := 1, 0
	for i := 0; i < e.From && i < len(e.Source); i++ {
		if e.Source[i] == '\n' {
			line++
			col = 0
		} else {
			col++
		}
	}
	// find the source line
	lines := strings.Split(e.Source, "\n")
	src := ""
	if line-1 < len(lines) {
		src = lines[line-1]
	}
	snippet := fmt.Sprintf("\n | %s\n | %s^", src, strings.Repeat(".", col))
	return fmt.Sprintf("%s (%d:%d)%s", e.Message, line, col+1, snippet)
}

func newError(src string, from int, format string, args ...interface{}) *Error {
	return &Error{Message: fmt.Sprintf(format, args...), From: from, Source: src}
}

type lexer struct {
	src    string
	pos    int
	start  int
	tokens []token
	err    *Error
}

func lex(src string) ([]token, *Error) {
	l := &lexer{src: src}
	l.run()
	return l.tokens, l.err
}

func (l *lexer) peek() rune {
	if l.pos >= len(l.src) {
		return -1
	}
	r, _ := utf8.DecodeRuneInString(l.src[l.pos:])
	return r
}

func (l *lexer) peekAt(n int) rune {
	p := l.pos
	for i := 0; i < n; i++ {
		if p >= len(l.src) {
			return -1
		}
		_, w := utf8.DecodeRuneInString(l.src[p:])
		p += w
	}
	if p >= len(l.src) {
		return -1
	}
	r, _ := utf8.DecodeRuneInString(l.src[p:])
	return r
}

func (l *lexer) next() rune {
	if l.pos >= len(l.src) {
		return -1
	}
	r, w := utf8.DecodeRuneInString(l.src[l.pos:])
	l.pos += w
	return r
}

func (l *lexer) emit(kind tokenKind) {
	l.emitValue(kind, l.src[l.start:l.pos])
}

func (l *lexer) emitValue(kind tokenKind, value string) {
	l.tokens = append(l.tokens, token{kind: kind, value: value, from: l.start, to: l.pos})
	l.start = l.pos
}

func isIdentStart(r rune) bool {
	return r == '_' || r == '$' || unicode.IsLetter(r)
}

func isIdentPart(r rune) bool {
	return r == '_' || r == '$' || unicode.IsLetter(r) || unicode.IsDigit(r)
}

var operatorTokens = []string{
	"startsWith", "endsWith", "contains", "matches",
	"?.", "??", "**", "==", "!=", "<=", ">=", "&&", "||", "..", "::",
	"+", "-", "*", "/", "%", "^", "<", ">", "!", "?", ":", ",", "|", ";", "#",
	".", "=",
}

func (l *lexer) run() {
	for l.pos < len(l.src) {
		l.start = l.pos
		r := l.peek()
		switch {
		case r == ' ' || r == '\t' || r == '\n' || r == '\r':
			l.next()
			l.start = l.pos
		case unicode.IsDigit(r) || (r == '.' && unicode.IsDigit(l.peekAt(1))):
			l.scanNumber()
		case r == '"' || r == '\'' || r == '`':
			l.scanString(r)
		case r == '(' || r == ')' || r == '[' || r == ']' || r == '{' || r == '}':
			l.next()
			l.emit(tokBracket)
		case isIdentStart(r):
			for isIdentPart(l.peek()) {
				l.next()
			}
			word := l.src[l.start:l.pos]
			switch word {
			case "not", "in", "or", "and", "matches", "contains", "startsWith", "endsWith", "let", "if", "else":
				l.emit(tokOperator)
			default:
				l.emit(tokIdentifier)
			}
		default:
			matched := false
			for _, op := range operatorTokens {
				if strings.HasPrefix(l.src[l.pos:], op) {
					l.pos += len(op)
					l.emit(tokOperator)
					matched = true
					break
				}
			}
			if !matched {
				l.err = newError(l.src, l.pos, "unrecognized character: %#U", r)
				return
			}
		}
		if l.err != nil {
			return
		}
	}
	l.start = l.pos
	from := len(l.src) - 1
	if from < 0 {
		from = 0
	}
	l.tokens = append(l.tokens, token{kind: tokEOF, from: from, to: len(l.src)})
}

func (l *lexer) scanNumber() {
	if l.peek() == '0' && (l.peekAt(1) == 'x' || l.peekAt(1) == 'X' || l.peekAt(1) == 'o' || l.peekAt(1) == 'O' || l.peekAt(1) == 'b' || l.peekAt(1) == 'B') {
		l.next()
		l.next()
		for unicode.IsDigit(l.peek()) || strings.ContainsRune("abcdefABCDEF_", l.peek()) {
			l.next()
		}
		l.emit(tokNumber)
		return
	}
	for unicode.IsDigit(l.peek()) || l.peek() == '_' {
		l.next()
	}
	if l.peek() == '.' && unicode.IsDigit(l.peekAt(1)) {
		l.next()
		for unicode.IsDigit(l.peek()) || l.peek() == '_' {
			l.next()
		}
	}
	if l.peek() == 'e' || l.peek() == 'E' {
		p := 1
		if l.peekAt(1) == '+' || l.peekAt(1) == '-' {
			p = 2
		}
		if unicode.IsDigit(l.peekAt(p)) {
			for i := 0; i < p; i++ {
				l.next()
			}
			for unicode.IsDigit(l.peek()) {
				l.next()
			}
		}
	}
	l.emit(tokNumber)
}

func (l *lexer) scanString(quote rune) {
	l.next() // opening quote
	var b strings.Builder
	for {
		r := l.next()
		if r == -1 {
			l.err = newError(l.src, l.start, "literal not terminated")
			return
		}
		if r == quote {
			break
		}
		if r == '\\' && quote != '`' {
			e := l.next()
			switch e {
			case 'n':
				b.WriteByte('\n')
			case 't':
				b.WriteByte('\t')
			case 'r':
				b.WriteByte('\r')
			case 'a':
				b.WriteByte('\a')
			case 'b':
				b.WriteByte('\b')
			case 'f':
				b.WriteByte('\f')
			case 'v':
				b.WriteByte('\v')
			case '\\':
				b.WriteByte('\\')
			case '\'':
				b.WriteByte('\'')
			case '"':
				b.WriteByte('"')
			case '`':
				b.WriteByte('`')
			case -1:
				l.err = newError(l.src, l.start, "literal not terminated")
				return
			default:
				b.WriteRune('\\')
				b.WriteRune(e)
			}
			continue
		}
		b.WriteRune(r)
	}
	l.emitValue(tokString, b.String())
}
EOF
echo ok"}

