package expr

import (
	"fmt"
	"strconv"
	"strings"
)

type associativity int

const (
	left associativity = iota
	right
)

type operatorInfo struct {
	precedence    int
	associativity associativity
}

var unaryOperators = map[string]operatorInfo{
	"not": {50, left},
	"!":   {50, left},
	"-":   {90, left},
	"+":   {90, left},
}

var binaryOperators = map[string]operatorInfo{
	"|":          {0, left},
	"or":         {10, left},
	"||":         {10, left},
	"and":        {15, left},
	"&&":         {15, left},
	"==":         {20, left},
	"!=":         {20, left},
	"<":          {20, left},
	">":          {20, left},
	">=":         {20, left},
	"<=":         {20, left},
	"in":         {20, left},
	"matches":    {20, left},
	"contains":   {20, left},
	"startsWith": {20, left},
	"endsWith":   {20, left},
	"..":         {25, left},
	"+":          {30, left},
	"-":          {30, left},
	"*":          {60, left},
	"/":          {60, left},
	"%":          {60, left},
	"**":         {70, right},
	"^":          {70, right},
	"??":         {500, left},
}

// builtins that take predicate (closure) arguments
var predicateBuiltins = map[string]bool{
	"all": true, "none": true, "any": true, "one": true, "filter": true, "map": true,
	"count": true, "sum": true, "find": true, "findIndex": true, "findLast": true, "findLastIndex": true,
	"groupBy": true, "sortBy": true, "reduce": true,
}

type parser struct {
	src     string
	tokens  []token
	current token
	pos     int
	err     *Error
	depth   int
}

func parse(src string) (node, *Error) {
	tokens, err := lex(src)
	if err != nil {
		return nil, err
	}
	p := &parser{src: src, tokens: tokens}
	p.current = tokens[0]
	n := p.parseExpression(0)
	if p.err == nil && !p.current.is(tokEOF) {
		p.error("unexpected token %v", p.current)
	}
	if p.err != nil {
		return nil, p.err
	}
	return n, nil
}

func (p *parser) error(format string, args ...interface{}) {
	p.errorAt(p.current.from, format, args...)
}

func (p *parser) errorAt(from int, format string, args ...interface{}) {
	if p.err == nil {
		p.err = newError(p.src, from, format, args...)
	}
}

func (p *parser) next() {
	p.pos++
	if p.pos >= len(p.tokens) {
		p.error("unexpected end of expression")
		return
	}
	p.current = p.tokens[p.pos]
}

func (p *parser) expect(kind tokenKind, values ...string) {
	if p.current.is(kind, values...) {
		p.next()
		return
	}
	p.error("unexpected token %v", p.current)
}

func (p *parser) parseExpression(precedence int) node {
	if p.err != nil {
		return nil
	}
	if precedence == 0 && p.current.is(tokOperator, "let") {
		return p.parseVariableDeclaration()
	}
	nodeLeft := p.parsePrimary()
	prevOperator := ""
	opToken := p.current
	for opToken.is(tokOperator) && p.err == nil {
		negate := false
		notToken := token{}
		if opToken.is(tokOperator, "not") {
			p.next()
			notToken = p.current
			negate = true
			opToken = p.current
		}
		op, ok := binaryOperators[opToken.value]
		if !ok {
			if negate {
				p.errorAt(notToken.from, "unexpected token %v", notToken)
			}
			break
		}
		if op.precedence < precedence {
			if negate {
				p.errorAt(notToken.from, "unexpected token %v", notToken)
			}
			break
		}
		p.next()
		if opToken.value == "|" {
			nodeLeft = p.parsePipe(nodeLeft)
			opToken = p.current
			continue
		}
		var nodeRight node
		if op.associativity == left {
			nodeRight = p.parseExpression(op.precedence + 1)
		} else {
			nodeRight = p.parseExpression(op.precedence)
		}
		var n node = &binaryNode{from: opToken.from, operator: opToken.value, left: nodeLeft, right: nodeRight}
		if negate {
			n = &unaryNode{from: notToken.from, operator: "not", node: n}
		}
		nodeLeft = n
		prevOperator = opToken.value
		_ = prevOperator
		opToken = p.current
	}
	if precedence == 0 && p.err == nil {
		nodeLeft = p.parseConditional(nodeLeft)
	}
	return nodeLeft
}

func (p *parser) parseVariableDeclaration() node {
	from := p.current.from
	p.expect(tokOperator, "let")
	name := p.current
	p.expect(tokIdentifier)
	p.expect(tokOperator, "=")
	value := p.parseExpression(0)
	p.expect(tokOperator, ";")
	expr := p.parseExpression(0)
	return &variableDeclaratorNode{from: from, name: name.value, value: value, expr: expr}
}

func (p *parser) parseConditional(n node) node {
	for p.current.is(tokOperator, "?") && p.err == nil {
		from := p.current.from
		p.next()
		var exp1, exp2 node
		if !p.current.is(tokOperator, ":") {
			exp1 = p.parseExpression(0)
			p.expect(tokOperator, ":")
			exp2 = p.parseExpression(0)
		} else {
			p.next()
			exp1 = n
			exp2 = p.parseExpression(0)
		}
		n = &conditionalNode{from: from, cond: n, exp1: exp1, exp2: exp2}
	}
	return n
}

func (p *parser) parsePrimary() node {
	if p.err != nil {
		return nil
	}
	tok := p.current
	if tok.is(tokOperator) {
		if op, ok := unaryOperators[tok.value]; ok {
			p.next()
			expr := p.parseExpression(op.precedence)
			n := &unaryNode{from: tok.from, operator: tok.value, node: expr}
			return p.parsePostfix(n)
		}
	}
	if tok.is(tokBracket, "(") {
		p.next()
		expr := p.parseExpression(0)
		p.expect(tokBracket, ")")
		return p.parsePostfix(expr)
	}
	if p.depth > 0 {
		if tok.is(tokOperator, "#") || tok.is(tokOperator, ".") {
			name := ""
			if tok.is(tokOperator, "#") {
				p.next()
				if p.current.is(tokIdentifier) {
					name = p.current.value
					p.next()
				}
				n := &pointerNode{from: tok.from, name: name}
				return p.parsePostfix(n)
			}
			// ".Name" shorthand for "#.Name"
			n := &pointerNode{from: tok.from}
			return p.parsePostfix(n)
		}
	} else {
		if tok.is(tokOperator, "#") || tok.is(tokOperator, ".") {
			p.error("cannot use pointer accessor outside closure")
			return nil
		}
	}
	if tok.is(tokOperator, "::") {
		p.next()
		tok = p.current
		p.expect(tokIdentifier)
		return p.parsePostfix(p.parseCall(tok, true))
	}
	return p.parseSecondary()
}

func (p *parser) parseSecondary() node {
	var n node
	tok := p.current
	switch tok.kind {
	case tokIdentifier:
		p.next()
		switch tok.value {
		case "true":
			n = &boolNode{from: tok.from, value: true}
			return n
		case "false":
			n = &boolNode{from: tok.from, value: false}
			return n
		case "nil":
			n = &nilNode{from: tok.from}
			return n
		default:
			if p.current.is(tokBracket, "(") {
				n = p.parseCall(tok, false)
			} else {
				n = &identifierNode{from: tok.from, value: tok.value}
			}
		}
	case tokNumber:
		p.next()
		value := strings.ReplaceAll(tok.value, "_", "")
		var nn node
		switch {
		case strings.HasPrefix(value, "0x") || strings.HasPrefix(value, "0X"):
			number, err := strconv.ParseInt(value, 0, 64)
			if err != nil {
				p.errorAt(tok.from, "invalid hex literal: %v", err)
			}
			nn = &integerNode{from: tok.from, value: int(number)}
		case strings.HasPrefix(value, "0b") || strings.HasPrefix(value, "0B"):
			number, err := strconv.ParseInt(value, 0, 64)
			if err != nil {
				p.errorAt(tok.from, "invalid binary literal: %v", err)
			}
			nn = &integerNode{from: tok.from, value: int(number)}
		case strings.HasPrefix(value, "0o") || strings.HasPrefix(value, "0O"):
			number, err := strconv.ParseInt(value, 0, 64)
			if err != nil {
				p.errorAt(tok.from, "invalid octal literal: %v", err)
			}
			nn = &integerNode{from: tok.from, value: int(number)}
		case strings.ContainsAny(value, ".eE"):
			number, err := strconv.ParseFloat(value, 64)
			if err != nil {
				p.errorAt(tok.from, "invalid float literal: %v", err)
			}
			nn = &floatNode{from: tok.from, value: number}
		default:
			number, err := strconv.ParseInt(value, 10, 64)
			if err != nil {
				p.errorAt(tok.from, "invalid integer literal: %v", err)
			}
			nn = &integerNode{from: tok.from, value: int(number)}
		}
		return p.parsePostfix(nn)
	case tokString:
		p.next()
		n = &stringNode{from: tok.from, value: tok.value}
	default:
		if tok.is(tokBracket, "[") {
			n = p.parseArrayExpression(tok)
		} else if tok.is(tokBracket, "{") {
			n = p.parseMapExpression(tok)
		} else {
			p.error("unexpected token %v", tok)
			return nil
		}
	}
	return p.parsePostfix(n)
}

func (p *parser) parseCall(tok token, checkOverrides bool) node {
	var n node
	if predicateBuiltins[tok.value] {
		p.expect(tokBracket, "(")
		var args []node
		if !p.current.is(tokBracket, ")") {
			args = append(args, p.parseExpression(0))
			for p.current.is(tokOperator, ",") && p.err == nil {
				p.next()
				args = append(args, p.parseClosure())
			}
		}
		p.expect(tokBracket, ")")
		n = &builtinNode{from: tok.from, name: tok.value, arguments: args}
	} else if _, ok := builtins[tok.value]; ok {
		args := p.parseArguments()
		n = &builtinNode{from: tok.from, name: tok.value, arguments: args}
	} else {
		args := p.parseArguments()
		n = &callNode{from: tok.from, callee: &identifierNode{from: tok.from, value: tok.value}, arguments: args}
	}
	return n
}

func (p *parser) parseClosure() node {
	from := p.current.from
	p.depth++
	n := p.parseExpression(0)
	p.depth--
	return &closureNode{from: from, node: n}
}

func (p *parser) parseArguments() []node {
	p.expect(tokBracket, "(")
	var nodes []node
	for !p.current.is(tokBracket, ")") && p.err == nil {
		if len(nodes) > 0 {
			p.expect(tokOperator, ",")
		}
		nodes = append(nodes, p.parseExpression(0))
	}
	p.expect(tokBracket, ")")
	return nodes
}

func (p *parser) parseArrayExpression(tok token) node {
	var nodes []node
	p.expect(tokBracket, "[")
	for !p.current.is(tokBracket, "]") && p.err == nil {
		if len(nodes) > 0 {
			p.expect(tokOperator, ",")
			if p.current.is(tokBracket, "]") {
				break
			}
		}
		nodes = append(nodes, p.parseExpression(0))
	}
	p.expect(tokBracket, "]")
	return &arrayNode{from: tok.from, nodes: nodes}
}

func (p *parser) parseMapExpression(tok token) node {
	p.expect(tokBracket, "{")
	var pairs []pairNode
	for !p.current.is(tokBracket, "}") && p.err == nil {
		if len(pairs) > 0 {
			p.expect(tokOperator, ",")
			if p.current.is(tokBracket, "}") {
				break
			}
		}
		var key node
		if p.current.is(tokNumber) || p.current.is(tokString) || p.current.is(tokIdentifier) {
			key = &stringNode{from: p.current.from, value: p.current.value}
			p.next()
		} else if p.current.is(tokBracket, "(") {
			key = p.parseExpression(0)
		} else {
			p.error("a map key must be a quoted string, a number, a identifier, or an expression enclosed in parentheses (unexpected token %v)", p.current)
			return nil
		}
		p.expect(tokOperator, ":")
		value := p.parseExpression(0)
		pairs = append(pairs, pairNode{key: key, value: value})
	}
	p.expect(tokBracket, "}")
	return &mapNode{from: tok.from, pairs: pairs}
}

func (p *parser) parsePostfix(n node) node {
	for p.err == nil {
		tok := p.current
		if tok.is(tokOperator, ".") || tok.is(tokOperator, "?.") {
			p.next()
			propTok := p.current
			if !propTok.is(tokIdentifier) && !(propTok.is(tokOperator) && isIdentWord(propTok.value)) {
				p.error("expected name")
				return nil
			}
			p.next()
			prop := &stringNode{from: propTok.from, value: propTok.value}
			optional := tok.is(tokOperator, "?.")
			if p.current.is(tokBracket, "(") {
				args := p.parseArguments()
				n = &callNode{from: propTok.from, callee: &memberNode{from: propTok.from, node: n, property: prop, optional: optional, method: true}, arguments: args}
			} else {
				n = &memberNode{from: propTok.from, node: n, property: prop, optional: optional, method: true}
			}
		} else if tok.is(tokBracket, "[") {
			p.next()
			var from, to node
			if p.current.is(tokOperator, ":") {
				p.next()
				if !p.current.is(tokBracket, "]") {
					to = p.parseExpression(0)
				}
				n = &sliceNode{from: tok.from, node: n, fromNode: from, toNode: to}
				p.expect(tokBracket, "]")
			} else {
				from = p.parseExpression(0)
				if p.current.is(tokOperator, ":") {
					p.next()
					if !p.current.is(tokBracket, "]") {
						to = p.parseExpression(0)
					}
					n = &sliceNode{from: tok.from, node: n, fromNode: from, toNode: to}
				} else {
					n = &memberNode{from: tok.from, node: n, property: from}
				}
				p.expect(tokBracket, "]")
			}
		} else if tok.is(tokBracket, "(") {
			args := p.parseArguments()
			n = &callNode{from: n.loc(), callee: n, arguments: args}
		} else {
			break
		}
	}
	return n
}

func isIdentWord(s string) bool {
	for i, r := range s {
		if i == 0 && !isIdentStart(r) {
			return false
		}
		if !isIdentPart(r) {
			return false
		}
	}
	return s != ""
}

func (p *parser) parsePipe(n node) node {
	tok := p.current
	if !tok.is(tokIdentifier) {
		p.error("unexpected token %v", tok)
		return nil
	}
	p.next()
	var args []node
	if predicateBuiltins[tok.value] {
		p.expect(tokBracket, "(")
		args = append(args, n)
		if !p.current.is(tokBracket, ")") {
			args = append(args, p.parseClosure())
			for p.current.is(tokOperator, ",") && p.err == nil {
				p.next()
				args = append(args, p.parseClosure())
			}
		}
		p.expect(tokBracket, ")")
		return p.parsePostfix(&builtinNode{from: tok.from, name: tok.value, arguments: args})
	}
	args = append(args, n)
	args = append(args, p.parseArguments()...)
	if _, ok := builtins[tok.value]; ok {
		return p.parsePostfix(&builtinNode{from: tok.from, name: tok.value, arguments: args})
	}
	return p.parsePostfix(&callNode{from: tok.from, callee: &identifierNode{from: tok.from, value: tok.value}, arguments: args})
}

