func throw(from int, format string, args ...interface{}) {
	panic(&runtimeError{msg: fmt.Sprintf(format, args...), from: from})
}

// Compile parses and type checks an expression. env holds the variables
// (used for type information) and funcs the custom functions.
func Compile(src string, env map[string]interface{}, funcs []*Function) (*Program, error) {
	tree, err := parse(src)
	if err != nil {
		return nil, err
	}
	p := &Program{src: src, tree: tree, funcs: map[string]*Function{}}
	for _, f := range funcs {
		p.funcs[f.Name] = f
	}
	c := &checker{src: src, env: env, funcs: p.funcs}
	if cerr := c.check(tree); cerr != nil {
		return nil, cerr
	}
	return p, nil
}

// Run evaluates the program.
func (p *Program) Run(env map[string]interface{}) (result interface{}, err error) {
	defer func() {
		if r := recover(); r != nil {
			switch e := r.(type) {
			case *runtimeError:
				err = &Error{Message: e.msg, From: e.from, Source: p.src}
			case error:
				err = &Error{Message: e.Error(), From: 0, Source: p.src}
			default:
				err = &Error{Message: fmt.Sprint(r), From: 0, Source: p.src}
			}
		}
	}()
	ev := &evaluator{env: env, funcs: p.funcs, vars: map[string]interface{}{}}
	result = ev.eval(p.tree)
	return result, nil
}

type evaluator struct {
	env   map[string]interface{}
	funcs map[string]*Function
	vars  map[string]interface{}
	// closure scope
	scopes []*scope
}

type scope struct {
	item  interface{}
	index int
	acc   interface{}
	len   int
}

func (ev *evaluator) eval(n node) interface{} {
	switch n := n.(type) {
	case *nilNode:
		return nil
	case *identifierNode:
		if v, ok := ev.vars[n.value]; ok {
			return v
		}
		if v, ok := ev.env[n.value]; ok {
			return v
		}
		if f, ok := ev.funcs[n.value]; ok {
			return f.Fn.Interface()
		}
		throw(n.from, "unknown name %v", n.value)
	case *integerNode:
		return n.value
	case *floatNode:
		return n.value
	case *boolNode:
		return n.value
	case *stringNode:
		return n.value
	case *unaryNode:
		v := ev.eval(n.node)
		switch n.operator {
		case "not", "!":
			b, ok := v.(bool)
			if !ok {
				throw(n.from, "invalid operation: %s (mismatched type %T)", n.operator, v)
			}
			return !b
		case "-":
			return negate(n.from, v)
		case "+":
			return v
		}
	case *binaryNode:
		return ev.evalBinary(n)
	case *conditionalNode:
		c := ev.eval(n.cond)
		b, ok := c.(bool)
		if !ok {
			throw(n.from, "non-bool value in condition")
		}
		if b {
			return ev.eval(n.exp1)
		}
		return ev.eval(n.exp2)
	case *arrayNode:
		arr := make([]interface{}, 0, len(n.nodes))
		for _, e := range n.nodes {
			arr = append(arr, ev.eval(e))
		}
		return arr
	case *mapNode:
		m := make(map[string]interface{}, len(n.pairs))
		for _, pr := range n.pairs {
			k := ev.eval(pr.key)
			m[fmt.Sprint(k)] = ev.eval(pr.value)
		}
		return m
	case *memberNode:
		base := ev.eval(n.node)
		if n.optional && base == nil {
			return nil
		}
		prop := ev.eval(n.property)
		return fetch(n.from, base, prop)
	case *sliceNode:
		base := ev.eval(n.node)
		v := reflect.ValueOf(base)
		if v.Kind() != reflect.Slice && v.Kind() != reflect.Array && v.Kind() != reflect.String {
			throw(n.from, "cannot slice %T", base)
		}
		l := v.Len()
		from, to := 0, l
		if n.fromNode != nil {
			from = toInt(n.from, ev.eval(n.fromNode))
		}
		if n.toNode != nil {
			to = toInt(n.from, ev.eval(n.toNode))
		}
		if from < 0 {
			from = l + from
		}
		if to < 0 {
			to = l + to
		}
		if from < 0 || to > l || from > to {
			throw(n.from, "slice [%v:%v] out of range (length is %v)", from, to, l)
		}
		return v.Slice(from, to).Interface()
	case *callNode:
		return ev.evalCall(n)
	case *builtinNode:
		return ev.evalBuiltin(n)
	case *closureNode:
		return ev.eval(n.node)
	case *pointerNode:
		if len(ev.scopes) == 0 {
			throw(n.from, "cannot use pointer accessor outside closure")
		}
		s := ev.scopes[len(ev.scopes)-1]
		switch n.name {
		case "", "index":
			if n.name == "index" {
				return s.index
			}
			return s.item
		case "acc":
			return s.acc
		}
		return s.item
	case *variableDeclaratorNode:
		ev.vars[n.name] = ev.eval(n.value)
		return ev.eval(n.expr)
	}
	throw(n.loc(), "unsupported node %T", n)
	return nil
}

func (ev *evaluator) evalCall(n *callNode) interface{} {
	var fn reflect.Value
	name := ""
	switch c := n.callee.(type) {
	case *identifierNode:
		name = c.value
		if f, ok := ev.funcs[c.value]; ok {
			fn = f.Fn
		} else if v, ok := ev.vars[c.value]; ok {
			fn = reflect.ValueOf(v)
		} else if v, ok := ev.env[c.value]; ok {
			fn = reflect.ValueOf(v)
		} else {
			throw(c.from, "unknown name %v", c.value)
		}
	default:
		v := ev.eval(n.callee)
		if m, ok := n.callee.(*memberNode); ok && m.optional && v == nil {
			return nil
		}
		fn = reflect.ValueOf(v)
	}
	if fn.Kind() != reflect.Func {
		throw(n.from, "%v is not callable", name)
	}
	args := make([]interface{}, len(n.arguments))
	for i, a := range n.arguments {
		args[i] = ev.eval(a)
	}
	return callFunc(n.from, fn, args)
}

func callFunc(from int, fn reflect.Value, args []interface{}) interface{} {
	t := fn.Type()
	in := make([]reflect.Value, 0, len(args))
	for i, a := range args {
		var pt reflect.Type
		if t.IsVariadic() && i >= t.NumIn()-1 {
			pt = t.In(t.NumIn() - 1).Elem()
		} else if i < t.NumIn() {
			pt = t.In(i)
		} else {
			throw(from, "too many arguments to call")
		}
		in = append(in, convertArg(from, a, pt))
	}
	if !t.IsVariadic() && len(in) < t.NumIn() {
		throw(from, "not enough arguments to call")
	}
	out := fn.Call(in)
	if len(out) == 0 {
		return nil
	}
	if len(out) == 2 {
		if err, ok := out[1].Interface().(error); ok && err != nil {
			panic(err)
		}
	}
	return out[0].Interface()
}

func convertArg(from int, a interface{}, pt reflect.Type) reflect.Value {
	if a == nil {
		return reflect.Zero(pt)
	}
	v := reflect.ValueOf(a)
	if v.Type().AssignableTo(pt) {
		return v
	}
	if v.Type().ConvertibleTo(pt) {
		switch pt.Kind() {
		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
			reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64,
			reflect.Float32, reflect.Float64:
			if isNumberKind(v.Kind()) {
				return v.Convert(pt)
			}
		case reflect.String:
			if v.Kind() == reflect.String {
				return v.Convert(pt)
			}
		case reflect.Interface:
			return v.Convert(pt)
		default:
			return v.Convert(pt)
		}
	}
	if pt.Kind() == reflect.Interface && v.Type().Implements(pt) {
		return v
	}
	throw(from, "cannot use %T as argument (type %v)", a, pt)
	return reflect.Value{}
}

func isNumberKind(k reflect.Kind) bool {
	switch k {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64,
		reflect.Float32, reflect.Float64:
		return true
	}
	return false
}

// fetch implements member access.
func fetch(from int, base interface{}, i interface{}) interface{} {
	v := reflect.ValueOf(base)
	if v.Kind() == reflect.Invalid {
		throw(from, "cannot fetch %v from %T", i, base)
	}
	if v.NumMethod() > 0 {
		if methodName, ok := i.(string); ok {
			method := v.MethodByName(methodName)
			if method.IsValid() {
				return method.Interface()
			}
		}
	}
	for v.Kind() == reflect.Ptr || v.Kind() == reflect.Interface {
		if v.IsNil() {
			break
		}
		v = v.Elem()
	}
	switch v.Kind() {
	case reflect.Array, reflect.Slice, reflect.String:
		index := toInt(from, i)
		l := v.Len()
		if index < 0 {
			index = l + index
		}
		if index < 0 || index >= l {
			throw(from, "index out of range: %v (array length is %v)", index, l)
		}
		value := v.Index(index)
		if value.IsValid() {
			if v.Kind() == reflect.String {
				return string(value.Interface().(uint8))
			}
			return value.Interface()
		}
	case reflect.Map:
		var value reflect.Value
		if i == nil {
			value = v.MapIndex(reflect.Zero(v.Type().Key()))
		} else {
			kv := reflect.ValueOf(i)
			if kv.Type().ConvertibleTo(v.Type().Key()) {
				value = v.MapIndex(kv.Convert(v.Type().Key()))
			}
		}
		if value.IsValid() {
			return value.Interface()
		}
		return reflect.Zero(v.Type().Elem()).Interface()
	case reflect.Struct:
		fieldName, ok := i.(string)
		if ok {
			value := v.FieldByName(fieldName)
			if value.IsValid() {
				return value.Interface()
			}
		}
	}
	throw(from, "cannot fetch %v from %T", i, base)
	return nil
}

func toInt(from int, v interface{}) int {
	switch n := v.(type) {
	case int:
		return n
	case int8:
		return int(n)
	case int16:
		return int(n)
	case int32:
		return int(n)
	case int64:
		return int(n)
	case uint:
		return int(n)
	case uint8:
		return int(n)
	case uint16:
		return int(n)
	case uint32:
		return int(n)
	case uint64:
		return int(n)
	case float32:
		return int(n)
	case float64:
		return int(n)
	}
	throw(from, "invalid operation: int(%T)", v)
	return 0
}

func toFloat(v interface{}) (float64, bool) {
	switch n := v.(type) {
	case int:
		return float64(n), true
	case int8:
		return float64(n), true
	case int16:
		return float64(n), true
	case int32:
		return float64(n), true
	case int64:
		return float64(n), true
	case uint:
		return float64(n), true
	case uint8:
		return float64(n), true
	case uint16:
		return float64(n), true
	case uint32:
		return float64(n), true
	case uint64:
		return float64(n), true
	case float32:
		return float64(n), true
	case float64:
		return n, true
	}
	return 0, false
}

func isInt(v interface{}) bool {
	switch v.(type) {
	case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64:
		return true
	}
	return false
}

func isFloat(v interface{}) bool {
	switch v.(type) {
	case float32, float64:
		return true
	}
	return false
}

func negate(from int, v interface{}) interface{} {
	switch n := v.(type) {
	case int:
		return -n
	case int64:
		return -n
	case int32:
		return -n
	case float64:
		return -n
	case float32:
		return -n
	}
	throw(from, "invalid operation: - (mismatched type %T)", v)
	return nil
}

func (ev *evaluator) evalBinary(n *binaryNode) interface{} {
	switch n.operator {
	case "or", "||":
		l, ok := ev.eval(n.left).(bool)
		if !ok {
			throw(n.from, "invalid operation: %s (mismatched types)", n.operator)
		}
		if l {
			return true
		}
		r, ok := ev.eval(n.right).(bool)
		if !ok {
			throw(n.from, "invalid operation: %s (mismatched types)", n.operator)
		}
		return r
	case "and", "&&":
		l, ok := ev.eval(n.left).(bool)
		if !ok {
			throw(n.from, "invalid operation: %s (mismatched types)", n.operator)
		}
		if !l {
			return false
		}
		r, ok := ev.eval(n.right).(bool)
		if !ok {
			throw(n.from, "invalid operation: %s (mismatched types)", n.operator)
		}
		return r
	case "??":
		l := ev.eval(n.left)
		if l != nil {
			return l
		}
		return ev.eval(n.right)
	}
	l := ev.eval(n.left)
	r := ev.eval(n.right)
	return binaryOp(n.from, n.operator, l, r)
}

func binaryOp(from int, op string, l, r interface{}) interface{} {
	switch op {
	case "==":
		return equal(l, r)
	case "!=":
		return !equal(l, r)
	case "<", ">", "<=", ">=":
		return compare(from, op, l, r)
	case "+":
		if ls, ok := l.(string); ok {
			if rs, ok := r.(string); ok {
				return ls + rs
			}
		}
		return arith(from, op, l, r)
	case "-", "*", "/", "%", "**", "^":
		return arith(from, op, l, r)
	case "..":
		a := toInt(from, l)
		b := toInt(from, r)
		if b < a {
			return []int{}
		}
		out := make([]int, 0, b-a+1)
		for i := a; i <= b; i++ {
			out = append(out, i)
		}
		return out
	case "in":
		return contains(from, r, l)
	case "contains":
		ls, ok1 := l.(string)
		rs, ok2 := r.(string)
		if !ok1 || !ok2 {
			throw(from, "invalid operation: contains (mismatched types %T and %T)", l, r)
		}
		return strings.Contains(ls, rs)
	case "startsWith":
		ls, ok1 := l.(string)
		rs, ok2 := r.(string)
		if !ok1 || !ok2 {
			throw(from, "invalid operation: startsWith (mismatched types %T and %T)", l, r)
		}
		return strings.HasPrefix(ls, rs)
	case "endsWith":
		ls, ok1 := l.(string)
		rs, ok2 := r.(string)
		if !ok1 || !ok2 {
			throw(from, "invalid operation: endsWith (mismatched types %T and %T)", l, r)
		}
		return strings.HasSuffix(ls, rs)
	case "matches":
		ls, ok1 := l.(string)
		rs, ok2 := r.(string)
		if !ok1 || !ok2 {
			throw(from, "invalid operation: matches (mismatched types %T and %T)", l, r)
		}
		re, err := regexp.Compile(rs)
		if err != nil {
			throw(from, "%v", err)
		}
		return re.MatchString(ls)
	}
	throw(from, "unknown operator %s", op)
	return nil
}

func equal(l, r interface{}) bool {
	if lf, ok := toFloat(l); ok {
		if rf, ok := toFloat(r); ok {
			return lf == rf
		}
	}
	return reflect.DeepEqual(l, r)
}

func compare(from int, op string, l, r interface{}) bool {
	lf, ok1 := toFloat(l)
	rf, ok2 := toFloat(r)
	if ok1 && ok2 {
		switch op {
		case "<":
			return lf < rf
		case ">":
			return lf > rf
		case "<=":
			return lf <= rf
		case ">=":
			return lf >= rf
		}
	}
	ls, ok1 := l.(string)
	rs, ok2 := r.(string)
	if ok1 && ok2 {
		switch op {
		case "<":
			return ls < rs
		case ">":
			return ls > rs
		case "<=":
			return ls <= rs
		case ">=":
			return ls >= rs
		}
	}
	throw(from, "invalid operation: %s (mismatched types %T and %T)", op, l, r)
	return false
}

func arith(from int, op string, l, r interface{}) interface{} {
	if isInt(l) && isInt(r) {
		a := toInt(from, l)
		b := toInt(from, r)
		switch op {
		case "+":
			return a + b
		case "-":
			return a - b
		case "*":
			return a * b
		case "/":
			return float64(a) / float64(b)
		case "%":
			if b == 0 {
				throw(from, "integer divide by zero")
			}
			return a % b
		case "**", "^":
			return math.Pow(float64(a), float64(b))
		}
	}
	lf, ok1 := toFloat(l)
	rf, ok2 := toFloat(r)
	if ok1 && ok2 {
		switch op {
		case "+":
			return lf + rf
		case "-":
			return lf - rf
		case "*":
			return lf * rf
		case "/":
			return lf / rf
		case "%":
			return math.Mod(lf, rf)
		case "**", "^":
			return math.Pow(lf, rf)
		}
	}
	throw(from, "invalid operation: %s (mismatched types %T and %T)", op, l, r)
	return nil
}

func contains(from int, container interface{}, item interface{}) bool {
	v := reflect.ValueOf(container)
	switch v.Kind() {
	case reflect.Slice, reflect.Array:
		for i := 0; i < v.Len(); i++ {
			if equal(v.Index(i).Interface(), item) {
				return true
			}
		}
		return false
	case reflect.Map:
		if item == nil {
			return false
		}
		kv := reflect.ValueOf(item)
		if kv.Type().ConvertibleTo(v.Type().Key()) {
			return v.MapIndex(kv.Convert(v.Type().Key())).IsValid()
		}
		return false
	case reflect.Struct:
		if s, ok := item.(string); ok {
			return v.FieldByName(s).IsValid()
		}
	case reflect.Invalid:
		return false
	}
	throw(from, "invalid operation: in (mismatched types %T and %T)", item, container)
	return false
}

// ---- helpers for builtins ----

func toSlice(from int, v interface{}) []interface{} {
	rv := reflect.ValueOf(v)
	switch rv.Kind() {
	case reflect.Slice, reflect.Array:
		out := make([]interface{}, rv.Len())
		for i := 0; i < rv.Len(); i++ {
			out[i] = rv.Index(i).Interface()
		}
		return out
	}
	throw(from, "cannot convert %T to array", v)
	return nil
}

func sortValues(from int, arr []interface{}, desc bool) {
	sort.SliceStable(arr, func(i, j int) bool {
		a, b := arr[i], arr[j]
		var less bool
		if af, ok := toFloat(a); ok {
			if bf, ok := toFloat(b); ok {
				less = af < bf
			} else {
				throw(from, "invalid argument for sort (mixed types)")
			}
		} else if as, ok := a.(string); ok {
			if bs, ok := b.(string); ok {
				less = as < bs
			} else {
				throw(from, "invalid argument for sort (mixed types)")
			}
		} else {
			throw(from, "invalid argument for sort (type %T)", a)
		}
		if desc {
			return !less && !equal(a, b)
		}
		return less
	})
}
EOF
echo ok"}

