		return strings.TrimSpace(s)
	case "trimPrefix":
		argc(1, 2)
		s := ev.str(from, args[0])
		p := " "
		if len(args) == 2 {
			p = ev.str(from, args[1])
		}
		return strings.TrimPrefix(s, p)
	case "trimSuffix":
		argc(1, 2)
		s := ev.str(from, args[0])
		p := " "
		if len(args) == 2 {
			p = ev.str(from, args[1])
		}
		return strings.TrimSuffix(s, p)
	case "upper":
		argc(1, 1)
		return strings.ToUpper(ev.str(from, args[0]))
	case "lower":
		argc(1, 1)
		return strings.ToLower(ev.str(from, args[0]))
	case "split":
		argc(2, 3)
		s := ev.str(from, args[0])
		sep := ev.str(from, args[1])
		if len(args) == 3 {
