		return toInterfaceSlice(strings.SplitAfter(s, sep))
	case "replace":
		argc(3, 3)
		return strings.ReplaceAll(ev.str(from, args[0]), ev.str(from, args[1]), ev.str(from, args[2]))
	case "repeat":
		argc(2, 2)
		cnt := toInt(from, ev.eval(args[1]))
		if cnt < 0 {
