		return strings.LastIndex(ev.str(from, args[0]), ev.str(from, args[1]))
	case "hasPrefix":
		argc(2, 2)
		return strings.HasPrefix(ev.str(from, args[0]), ev.str(from, args[1]))
	case "hasSuffix":
		argc(2, 2)
		return strings.HasSuffix(ev.str(from, args[0]), ev.str(from, args[1]))
