	return nil
}

func safeFetch(base, key interface{}) (out interface{}) {
	defer func() {
		if r := recover(); r != nil {
			out = nil
		}
	}()
	return fetch(0, base, key)
}

func (ev *evaluator) truthy(n node) bool {
	v := ev.eval(n)
	b, ok := v.(bool)
	if !ok {
		throw(n.loc(), "predicate should return boolean (got %T)", v)
	}
	return b
}

func (ev *evaluator) str(from int, n node) string {
	v := ev.eval(n)
	s, ok := v.(string)
	if !ok {
		throw(from, "invalid argument (type %T), expected string", v)
	}
	return s
}

func toInterfaceSlice(ss []string) []interface{} {
	out := make([]interface{}, len(ss))
	for i, s := range ss {
		out[i] = s
	}
	return out
}

func flatten(vals []interface{}) []interface{} {
	out := []interface{}{}
	for _, v := range vals {
		rv := reflect.ValueOf(v)
		if rv.Kind() == reflect.Slice || rv.Kind() == reflect.Array {
			out = append(out, flatten(toSlice(0, v))...)
		} else {
			out = append(out, v)
		}
	}
	return out
}

func sortFloats(fs []float64) {
	for i := 1; i < len(fs); i++ {
		for j := i; j > 0 && fs[j] < fs[j-1]; j-- {
			fs[j], fs[j-1] = fs[j-1], fs[j]
		}
	}
}

func sortStrings(ss []string) {
	for i := 1; i < len(ss); i++ {
		for j := i; j > 0 && ss[j] < ss[j-1]; j-- {
			ss[j], ss[j-1] = ss[j-1], ss[j]
		}
	}
}

func sortIndexByKeys(from int, idx []int, keys []interface{}, desc bool) {
	less := func(a, b interface{}) bool {
		if af, ok := toFloat(a); ok {
			if bf, ok := toFloat(b); ok {
				return af < bf
			}
		}
		if as, ok := a.(string); ok {
			if bs, ok := b.(string); ok {
				return as < bs
			}
		}
		throw(from, "invalid argument for sortBy (type %T)", a)
		return false
	}
	for i := 1; i < len(idx); i++ {
		for j := i; j > 0; j-- {
			a, b := keys[idx[j]], keys[idx[j-1]]
			var swap bool
			if desc {
				swap = less(b, a)
			} else {
				swap = less(a, b)
			}
			if !swap {
				break
			}
			idx[j], idx[j-1] = idx[j-1], idx[j]
		}
	}
}
