func (ev *evaluator) withScope(items []interface{}, fn func(s *scope) bool) {
	s := &scope{len: len(items)}
	ev.scopes = append(ev.scopes, s)
	defer func() { ev.scopes = ev.scopes[:len(ev.scopes)-1] }()
	for i, it := range items {
		s.item = it
		s.index = i
		if !fn(s) {
			break
		}
	}
