			if !ev.truthy(pred) {
				result = false
				return false
			}
			return true
		})
		return result
	case "none":
		pred := predicate()
		items := toSlice(from, ev.eval(args[0]))
		result := true
		ev.withScope(items, func(s *scope) bool {
			if ev.truthy(pred) {
				result = false
				return false
			}
			return true
