	}
	return false
}

func isIntType(t reflect.Type) bool {
	if t == nil {
		return true
	}
	switch t.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return true
	}
	return false
}

func isStringType(t reflect.Type) bool {
	return t != nil && t.Kind() == reflect.String
}

func isArrayType(t reflect.Type) bool {
	return t != nil && (t.Kind() == reflect.Slice || t.Kind() == reflect.Array)
}

func isInterface(t reflect.Type) bool {
	return t == nil || t.Kind() == reflect.Interface
}

// visit returns the static type of a node (nil when unknown).
func (c *checker) visit(n node) reflect.Type {
	if c.err != nil || n == nil {
		return nil
	}
	switch n := n.(type) {
	case *nilNode:
		return nil
	case *integerNode:
		return intType
	case *floatNode:
		return floatType
	case *boolNode:
		return boolType
	case *stringNode:
		return stringType
	case *identifierNode:
		for _, v := range c.vars {
			if v == n.value {
				return nil
			}
		}
		if v, ok := c.env[n.value]; ok {
			if v == nil {
				return nil
			}
			return reflect.TypeOf(v)
		}
		if f, ok := c.funcs[n.value]; ok {
			return f.Fn.Type()
		}
		c.fail(n.from, "unknown name %v", n.value)
		return nil
	case *unaryNode:
		t := c.visit(n.node)
		switch n.operator {
		case "not", "!":
			if t != nil && t.Kind() != reflect.Bool && !isInterface(t) {
				c.fail(n.from, "invalid operation: %s (mismatched type %v)", n.operator, t)
			}
			return boolType
		case "-", "+":
			if t != nil && !isNumeric(t) && !isInterface(t) {
				c.fail(n.from, "invalid operation: %s (mismatched type %v)", n.operator, t)
			}
			return t
		}
		return nil
	case *binaryNode:
		l := c.visit(n.left)
		r := c.visit(n.right)
		return c.binaryType(n, l, r)
	case *conditionalNode:
		c.visit(n.cond)
		t1 := c.visit(n.exp1)
		t2 := c.visit(n.exp2)
		if t1 == t2 {
			return t1
		}
		return nil
	case *arrayNode:
		for _, e := range n.nodes {
			c.visit(e)
		}
		return reflect.TypeOf([]interface{}{})
	case *mapNode:
		for _, p := range n.pairs {
			c.visit(p.key)
			c.visit(p.value)
		}
		return reflect.TypeOf(map[string]interface{}{})
	case *memberNode:
		base := c.visit(n.node)
		if _, ok := n.property.(*stringNode); ok && n.method {
			return c.memberType(n, base, n.property.(*stringNode).value)
		}
		pt := c.visit(n.property)
		if isArrayType(base) {
			if pt != nil && !isIntType(pt) && !isInterface(pt) {
				c.fail(n.from, "array elements can only be selected using an integer (got %v)", pt)
				return nil
			}
			return base.Elem()
		}
		if base != nil && base.Kind() == reflect.Map {
			return base.Elem()
		}
		if base != nil && base.Kind() == reflect.String {
			return stringType
		}
		return nil
	case *sliceNode:
		t := c.visit(n.node)
		c.visit(n.fromNode)
		c.visit(n.toNode)
		return t
	case *callNode:
		return c.callType(n)
	case *builtinNode:
		return c.builtinType(n)
	case *closureNode:
		c.depth++
		t := c.visit(n.node)
		c.depth--
		return t
	case *pointerNode:
		return nil
	case *variableDeclaratorNode:
		c.visit(n.value)
		c.vars = append(c.vars, n.name)
		t := c.visit(n.expr)
		c.vars = c.vars[:len(c.vars)-1]
		return t
	}
	return nil
}

func (c *checker) binaryType(n *binaryNode, l, r reflect.Type) reflect.Type {
	switch n.operator {
	case "or", "||", "and", "&&":
		return boolType
	case "==", "!=":
		return boolType
	case "<", ">", "<=", ">=":
		if l != nil && r != nil && !isInterface(l) && !isInterface(r) {
			if !(isNumeric(l) && isNumeric(r)) && !(isStringType(l) && isStringType(r)) {
				c.fail(n.from, "invalid operation: %s (mismatched types %v and %v)", n.operator, l, r)
			}
		}
		return boolType
	case "in":
		return boolType
	case "matches", "contains", "startsWith", "endsWith":
		if l != nil && !isStringType(l) && !isInterface(l) || r != nil && !isStringType(r) && !isInterface(r) {
			c.fail(n.from, "invalid operation: %s (mismatched types %v and %v)", n.operator, l, r)
		}
		return boolType
	case "..":
		return reflect.TypeOf([]int{})
	case "+":
		if l != nil && r != nil && !isInterface(l) && !isInterface(r) {
			if isStringType(l) && isStringType(r) {
				return stringType
			}
			if isNumeric(l) && isNumeric(r) {
				if isIntType(l) && isIntType(r) {
					return intType
				}
				return floatType
			}
			c.fail(n.from, "invalid operation: %s (mismatched types %v and %v)", n.operator, l, r)
			return nil
		}
		if isStringType(l) || isStringType(r) {
			return stringType
		}
		return nil
	case "-", "*", "%":
		if l != nil && r != nil && !isInterface(l) && !isInterface(r) {
			if !(isNumeric(l) && isNumeric(r)) {
				c.fail(n.from, "invalid operation: %s (mismatched types %v and %v)", n.operator, l, r)
				return nil
			}
			if isIntType(l) && isIntType(r) {
				return intType
			}
			return floatType
		}
		return nil
	case "/", "**", "^":
		if l != nil && r != nil && !isInterface(l) && !isInterface(r) {
			if !(isNumeric(l) && isNumeric(r)) {
				c.fail(n.from, "invalid operation: %s (mismatched types %v and %v)", n.operator, l, r)
				return nil
			}
		}
		return floatType
	case "??":
		if l == r {
			return l
		}
		return nil
	}
	return nil
}

func (c *checker) memberType(n *memberNode, base reflect.Type, name string) reflect.Type {
	if base == nil {
		return nil
	}
	if isArrayType(base) {
		c.fail(n.from, "array elements can only be selected using an integer (got string)")
		return nil
	}
	if m, ok := base.MethodByName(name); ok {
		return m.Type
	}
	t := base
	for t.Kind() == reflect.Ptr {
		t = t.Elem()
	}
	if t.Kind() == reflect.Struct {
		if f, ok := t.FieldByName(name); ok {
			return f.Type
		}
	}
	if t.Kind() == reflect.Map {
		return t.Elem()
	}
	if t.Kind() == reflect.Interface {
		return nil
	}
	if base.Kind() == reflect.Ptr {
		if m, ok := base.Elem().MethodByName(name); ok {
			return m.Type
		}
	}
	c.fail(n.from, "type %v has no field %v", base, name)
	return nil
}

func (c *checker) callType(n *callNode) reflect.Type {
	var ft reflect.Type
	name := ""
	switch callee := n.callee.(type) {
	case *identifierNode:
		name = callee.value
		if f, ok := c.funcs[callee.value]; ok {
			ft = f.Fn.Type()
		} else {
			ft = c.visit(callee)
		}
	default:
		ft = c.visit(n.callee)
		if m, ok := n.callee.(*memberNode); ok {
			if s, ok := m.property.(*stringNode); ok {
				name = s.value
			}
		}
	}
	argTypes := make([]reflect.Type, len(n.arguments))
	for i, a := range n.arguments {
		argTypes[i] = c.visit(a)
	}
	if c.err != nil {
		return nil
	}
	if ft == nil || ft.Kind() != reflect.Func {
		return nil
	}
	// method types obtained from MethodByName on an interface do not include
	// the receiver; from a concrete type they do. Our memberType returns the
	// method's type without receiver for interfaces and with receiver for
	// concrete types. Normalise by checking the callee kind.
	numIn := ft.NumIn()
	offset := 0
	if m, ok := n.callee.(*memberNode); ok {
		base := c.visit(m.node)
		if base != nil && base.Kind() != reflect.Interface {
			if _, isMethod := base.MethodByName(name); isMethod {
				offset = 1
			}
		}
	}
	params := numIn - offset
	if ft.IsVariadic() {
		if len(argTypes) < params-1 {
			c.fail(n.from, "not enough arguments to call %v", name)
			return nil
		}
	} else {
		if len(argTypes) > params {
			c.fail(n.from, "too many arguments to call %v", name)
			return nil
		}
		if len(argTypes) < params {
			c.fail(n.from, "not enough arguments to call %v", name)
			return nil
		}
	}
	for i, at := range argTypes {
		var pt reflect.Type
		if ft.IsVariadic() && i+offset >= numIn-1 {
			pt = ft.In(numIn - 1).Elem()
		} else {
			pt = ft.In(i + offset)
		}
		if at == nil || pt.Kind() == reflect.Interface {
			continue
		}
		if at.AssignableTo(pt) {
			continue
		}
		if isNumeric(at) && isNumeric(pt) {
			continue
		}
		if at.Kind() == reflect.Interface {
			continue
		}
		c.fail(n.arguments[i].loc(), "cannot use %v as argument (type %v) to call %v ", at, pt, name)
		return nil
	}
	if ft.NumOut() == 0 {
		return nil
	}
	return ft.Out(0)
}

func (c *checker) builtinType(n *builtinNode) reflect.Type {
	argTypes := make([]reflect.Type, len(n.arguments))
	for i, a := range n.arguments {
		if cl, ok := a.(*closureNode); ok {
			argTypes[i] = c.visit(cl)
		} else {
			argTypes[i] = c.visit(a)
		}
	}
	if c.err != nil {
		return nil
	}
	switch n.name {
	case "len":
		if len(n.arguments) != 1 {
			c.fail(n.from, "invalid number of arguments (expected 1, got %d)", len(n.arguments))
			return nil
		}
		t := argTypes[0]
		if t != nil && !isInterface(t) {
			switch t.Kind() {
			case reflect.Slice, reflect.Array, reflect.Map, reflect.String:
			default:
				c.fail(n.from, "invalid argument for len (type %v)", t)
				return nil
			}
		}
		return intType
	case "join":
		if len(n.arguments) < 1 || len(n.arguments) > 2 {
			c.fail(n.from, "invalid number of arguments (expected 1..2, got %d)", len(n.arguments))
			return nil
		}
		t := argTypes[0]
		if t != nil && !isInterface(t) {
			if !isArrayType(t) || (t.Elem().Kind() != reflect.String && t.Elem().Kind() != reflect.Interface) {
				c.fail(n.arguments[0].loc(), "cannot use %v as argument (type []string) to call join ", t)
				return nil
			}
		}
		return stringType
	case "upper", "lower", "trim", "trimPrefix", "trimSuffix", "replace", "repeat", "toJSON", "toBase64", "fromBase64", "string":
		for i, t := range argTypes {
			if n.name == "repeat" && i == 1 {
				continue
			}
			if n.name == "string" {
				continue
			}
			if t != nil && !isInterface(t) && t.Kind() != reflect.String {
				c.fail(n.arguments[i].loc(), "cannot use %v as argument (type string) to call %v ", t, n.name)
				return nil
			}
		}
		return stringType
	case "type":
		return stringType
	case "all", "any", "none", "one", "hasPrefix", "hasSuffix":
		return boolType
	case "count", "indexOf", "lastIndexOf", "int", "findIndex", "findLastIndex":
		return intType
	case "float", "ceil", "floor", "round", "mean", "median":
		return floatType
	case "map", "filter", "sortBy", "sort", "reverse", "uniq", "concat", "flatten", "keys", "values", "take", "toPairs", "split", "splitAfter":
		return reflect.TypeOf([]interface{}{})
	case "now":
		return reflect.TypeOf(timeType)
	}
	return nil
}
