// compileStatusBar compiles the WALK_STATUS_BAR expression. A compile error
// is fatal (panic), as in the original.
func compileStatusBar(src string) *statusBarProgram {
	sb := &statusBarProgram{}
	env := map[string]reflect.Type{
		"current_file": reflect.TypeOf((*fs.DirEntry)(nil)).Elem(),
		"files":        reflect.TypeOf([]fs.DirEntry{}),
	}
	funcs := []*expr.Function{
		{Name: "Sprintf", Fn: reflect.ValueOf(func(format string, a ...interface{}) string { return fmt.Sprintf(format, a...) })},
		{Name: "PadLeft", Fn: reflect.ValueOf(func(s string, n int) string { return fmt.Sprintf("%*s", n, s) })},
		{Name: "PadRight", Fn: reflect.ValueOf(func(s string, n int) string { return fmt.Sprintf("%*s", n, s) })},
		{Name: "Size", Fn: reflect.ValueOf(func() string { return sb.size() })},
		{Name: "Mode", Fn: reflect.ValueOf(func() string { return sb.mode() })},
		{Name: "ModTime", Fn: reflect.ValueOf(func() string { return sb.modTime() })},
		{Name: "Owner", Fn: reflect.ValueOf(func() string { return sb.owner() })},
	}
	prog, err := expr.Compile(src, env, funcs)
	if err != nil {
		panic(err)
	}
	sb.prog = prog
	return sb
}

func (sb *statusBarProgram) info() fs.FileInfo {
	if sb.m == nil {
		return nil
	}
	f := sb.m.currentFile()
	if f == nil {
		return nil
	}
	info, err := os.Lstat(sb.m.path + "/" + f.Name())
	if err != nil {
		return nil
	}
	return info
}

func (sb *statusBarProgram) size() string {
	info := sb.info()
	if info == nil {
		return ""
	}
	return humanSize(info.Size())
}

func humanSize(size int64) string {
	if size < 1024 {
		return fmt.Sprintf("%dB", size)
	}
	units := []string{"KB", "MB", "GB", "TB", "PB", "EB"}
	v := float64(size) / 1024
	i := 0
	for v >= 1024 && i < len(units)-1 {
		v /= 1024
		i++
	}
	return fmt.Sprintf("%.1f%s", v, units[i])
}

func (sb *statusBarProgram) mode() string {
	info := sb.info()
	if info == nil {
		return ""
	}
	return strings.ToLower(info.Mode().String())
}

func (sb *statusBarProgram) modTime() string {
	info := sb.info()
	if info == nil {
		return ""
	}
	t := info.ModTime()
	if t.Year() == time.Now().Year() {
		return t.Format("Jan 2 15:04")
	}
	return t.Format("Jan 2 2006")
}

func (sb *statusBarProgram) owner() string {
	info := sb.info()
	if info == nil {
		return ""
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok {
		return ""
	}
	uid := strconv.Itoa(int(stat.Uid))
	gid := strconv.Itoa(int(stat.Gid))
	if u, err := user.LookupId(uid); err == nil {
		uid = u.Username
	}
	if g, err := user.LookupGroupId(gid); err == nil {
		gid = g.Name
	}
	return uid + " " + gid
}

func (sb *statusBarProgram) eval(m *model) (string, error) {
	sb.m = m
	var current fs.DirEntry = m.currentFile()
	env := map[string]interface{}{
		"files": m.files,
	}
	if current != nil {
		env["current_file"] = current
	} else {
		env["current_file"] = nil
	}
	out, err := sb.prog.Run(env)
	if err != nil {
		return "", err
	}
	return fmt.Sprint(out), nil
}
