package main

import (
	"fmt"
	"image"
	"image/color"
	_ "image/gif"
	_ "image/jpeg"
	_ "image/png"
	"math"
	"os"
	"strings"
)

func (m *model) imagePreview(path string) string {
	f, err := os.Open(path)
	if err != nil {
		return roundedBox("No image preview available")
	}
	defer f.Close()
	img, _, err := image.Decode(f)
	if err != nil {
		return roundedBox("No image preview available")
	}
	w := m.width / 2
	h := 2 * (m.height - 1)
	if w < 1 || h < 1 {
		return ""
	}
	resized := lanczosResize(img, w, h)
	var b strings.Builder
	for y := 1; y+1 < h-1 || (y+1 == h-1 && false); y += 2 {
		if y+1 > h-1 {
			break
		}
		if y > 1 {
			b.WriteByte('\n')
		}
		for x := 1; x < w-1; x++ {
			upper := hexColor(resized.At(x, y))
			lower := hexColor(resized.At(x, y+1))
			st := style{profile: m.profile, fg: parseColor(m.profile, lower), bg: parseColor(m.profile, upper)}
			b.WriteString(st.render("▄"))
		}
	}
	return b.String()
}

func hexColor(c color.Color) string {
	r, g, b, _ := c.RGBA()
	return fmt.Sprintf("#%02x%02x%02x", r>>8, g>>8, b>>8)
}

// ---- Lanczos3 resampling with fixed point coefficients ----

func sinc(x float64) float64 {
	x = math.Abs(x) * math.Pi
	if x >= 1.220703e-4 {
		return math.Sin(x) / x
	}
	return 1
}

func lanczos3(in float64) float64 {
	if in > -3 && in < 3 {
		return sinc(in) * sinc(in/3.0)
	}
	return 0
}

func createWeights8(dy, filterLength int, scale float64) ([]int16, []int, int) {
	filterLength = filterLength * int(math.Max(math.Ceil(scale), 1))
	filterFactor := math.Min(1./scale, 1)
	coeffs := make([]int16, dy*filterLength)
	start := make([]int, dy)
	for y := 0; y < dy; y++ {
		interpX := scale*(float64(y)+0.5) - 0.5
		start[y] = int(interpX) - filterLength/2 + 1
		interpX -= float64(start[y])
		for i := 0; i < filterLength; i++ {
			in := (interpX - float64(i)) * filterFactor
			coeffs[y*filterLength+i] = int16(lanczos3(in) * 256)
		}
	}
	return coeffs, start, filterLength
}

func createWeights16(dy, filterLength int, scale float64) ([]int32, []int, int) {
	filterLength = filterLength * int(math.Max(math.Ceil(scale), 1))
	filterFactor := math.Min(1./scale, 1)
	coeffs := make([]int32, dy*filterLength)
	start := make([]int, dy)
	for y := 0; y < dy; y++ {
		interpX := scale*(float64(y)+0.5) - 0.5
		start[y] = int(interpX) - filterLength/2 + 1
		interpX -= float64(start[y])
		for i := 0; i < filterLength; i++ {
			in := (interpX - float64(i)) * filterFactor
			coeffs[y*filterLength+i] = int32(lanczos3(in) * 65536)
		}
	}
	return coeffs, start, filterLength
}

func clampUint8(in int32) uint8 {
	if in < 0 {
		return 0
	}
	if in > 255 {
		return 255
	}
	return uint8(in)
}

func clampUint16(in int64) uint16 {
	if in < 0 {
		return 0
	}
	if in > 65535 {
		return 65535
	}
	return uint16(in)
}

// resizeRGBA resamples along X writing the transposed result into out.
func resizeRGBA(in *image.RGBA, out *image.RGBA, coeffs []int16, offset []int, filterLength int) {
	newBounds := out.Bounds()
	maxX := in.Bounds().Dx() - 1
	for x := newBounds.Min.X; x < newBounds.Max.X; x++ {
		row := in.Pix[x*in.Stride:]
		for y := newBounds.Min.Y; y < newBounds.Max.Y; y++ {
			var rgba [4]int32
			var sum int32
			start := offset[y]
			ci := y * filterLength
			for i := 0; i < filterLength; i++ {
				coeff := coeffs[ci+i]
				if coeff != 0 {
					xi := start + i
					switch {
					case xi < 0:
						xi = 0
					case xi >= maxX:
						xi = maxX
					}
					rgba[0] += int32(coeff) * int32(row[xi*4+0])
					rgba[1] += int32(coeff) * int32(row[xi*4+1])
					rgba[2] += int32(coeff) * int32(row[xi*4+2])
					rgba[3] += int32(coeff) * int32(row[xi*4+3])
					sum += int32(coeff)
				}
			}
			xo := (y-newBounds.Min.Y)*out.Stride + (x-newBounds.Min.X)*4
			out.Pix[xo+0] = clampUint8(rgba[0] / sum)
			out.Pix[xo+1] = clampUint8(rgba[1] / sum)
			out.Pix[xo+2] = clampUint8(rgba[2] / sum)
			out.Pix[xo+3] = clampUint8(rgba[3] / sum)
		}
	}
}

func resizeNRGBA(in *image.NRGBA, out *image.RGBA, coeffs []int16, offset []int, filterLength int) {
	newBounds := out.Bounds()
	maxX := in.Bounds().Dx() - 1
	for x := newBounds.Min.X; x < newBounds.Max.X; x++ {
		row := in.Pix[x*in.Stride:]
		for y := newBounds.Min.Y; y < newBounds.Max.Y; y++ {
			var rgba [4]int32
			var sum int32
			start := offset[y]
			ci := y * filterLength
			for i := 0; i < filterLength; i++ {
				coeff := coeffs[ci+i]
				if coeff != 0 {
					xi := start + i
					switch {
					case xi < 0:
						xi = 0
					case xi >= maxX:
						xi = maxX
					}
					a := int32(row[xi*4+3])
					r := int32(row[xi*4+0]) * a / 0xff
					g := int32(row[xi*4+1]) * a / 0xff
					b := int32(row[xi*4+2]) * a / 0xff
					rgba[0] += int32(coeff) * r
					rgba[1] += int32(coeff) * g
					rgba[2] += int32(coeff) * b
					rgba[3] += int32(coeff) * a
					sum += int32(coeff)
				}
			}
			xo := (y-newBounds.Min.Y)*out.Stride + (x-newBounds.Min.X)*4
			out.Pix[xo+0] = clampUint8(rgba[0] / sum)
			out.Pix[xo+1] = clampUint8(rgba[1] / sum)
			out.Pix[xo+2] = clampUint8(rgba[2] / sum)
			out.Pix[xo+3] = clampUint8(rgba[3] / sum)
		}
	}
}

func resizeGray(in *image.Gray, out *image.Gray, coeffs []int16, offset []int, filterLength int) {
	newBounds := out.Bounds()
	maxX := in.Bounds().Dx() - 1
	for x := newBounds.Min.X; x < newBounds.Max.X; x++ {
		row := in.Pix[x*in.Stride:]
		for y := newBounds.Min.Y; y < newBounds.Max.Y; y++ {
			var gray int32
			var sum int32
			start := offset[y]
			ci := y * filterLength
			for i := 0; i < filterLength; i++ {
				coeff := coeffs[ci+i]
				if coeff != 0 {
					xi := start + i
					switch {
					case xi < 0:
						xi = 0
					case xi >= maxX:
						xi = maxX
					}
					gray += int32(coeff) * int32(row[xi])
					sum += int32(coeff)
				}
			}
			offset := (y-newBounds.Min.Y)*out.Stride + (x - newBounds.Min.X)
			out.Pix[offset] = clampUint8(gray / sum)
		}
	}
}

// ycc is a packed Y'CbCr image used for resampling.
type ycc struct {
	Pix    []uint8
	Stride int
	Rect   image.Rectangle
}

func newYCC(r image.Rectangle) *ycc {
	w, h := r.Dx(), r.Dy()
	return &ycc{Pix: make([]uint8, 3*w*h), Stride: 3 * w, Rect: r}
}

func imageYCbCrToYCC(in *image.YCbCr) *ycc {
	w, h := in.Rect.Dx(), in.Rect.Dy()
	r := image.Rect(0, 0, w, h)
	buf := make([]uint8, 3*w*h)
	p := &ycc{Pix: buf, Stride: 3 * w, Rect: r}
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			yi := in.YOffset(x+in.Rect.Min.X, y+in.Rect.Min.Y)
			ci := in.COffset(x+in.Rect.Min.X, y+in.Rect.Min.Y)
			i := (y*w + x) * 3
			buf[i+0] = in.Y[yi]
			buf[i+1] = in.Cb[ci]
			buf[i+2] = in.Cr[ci]
		}
	}
	return p
}

func (p *ycc) toYCbCr() *image.YCbCr {
	w, h := p.Rect.Dx(), p.Rect.Dy()
	out := image.NewYCbCr(p.Rect, image.YCbCrSubsampleRatio444)
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			i := (y*w + x) * 3
			yi := out.YOffset(x, y)
			ci := out.COffset(x, y)
			out.Y[yi] = p.Pix[i+0]
			out.Cb[ci] = p.Pix[i+1]
			out.Cr[ci] = p.Pix[i+2]
		}
	}
	return out
}

func resizeYCbCr(in *ycc, out *ycc, coeffs []int16, offset []int, filterLength int) {
	newBounds := out.Rect
	maxX := in.Rect.Dx() - 1
	for x := newBounds.Min.X; x < newBounds.Max.X; x++ {
		row := in.Pix[x*in.Stride:]
		for y := newBounds.Min.Y; y < newBounds.Max.Y; y++ {
			var p [3]int32
			var sum int32
			start := offset[y]
			ci := y * filterLength
			for i := 0; i < filterLength; i++ {
				coeff := coeffs[ci+i]
				if coeff != 0 {
					xi := start + i
					switch {
					case xi < 0:
						xi = 0
					case xi >= maxX:
						xi = maxX
					}
					p[0] += int32(coeff) * int32(row[xi*3+0])
					p[1] += int32(coeff) * int32(row[xi*3+1])
					p[2] += int32(coeff) * int32(row[xi*3+2])
					sum += int32(coeff)
				}
			}
			xo := (y-newBounds.Min.Y)*out.Stride + (x-newBounds.Min.X)*3
			out.Pix[xo+0] = clampUint8(p[0] / sum)
			out.Pix[xo+1] = clampUint8(p[1] / sum)
			out.Pix[xo+2] = clampUint8(p[2] / sum)
		}
	}
}

func resizeGeneric(in image.Image, out *image.RGBA64, coeffs []int32, offset []int, filterLength int) {
	newBounds := out.Bounds()
	maxX := in.Bounds().Dx() - 1
	for x := newBounds.Min.X; x < newBounds.Max.X; x++ {
		for y := newBounds.Min.Y; y < newBounds.Max.Y; y++ {
			var rgba [4]int64
			var sum int64
			start := offset[y]
			ci := y * filterLength
			for i := 0; i < filterLength; i++ {
				coeff := coeffs[ci+i]
				if coeff != 0 {
					xi := start + i
					switch {
					case xi < 0:
						xi = 0
					case xi >= maxX:
						xi = maxX
					}
					r, g, b, a := in.At(xi+in.Bounds().Min.X, x+in.Bounds().Min.Y).RGBA()
					rgba[0] += int64(coeff) * int64(r)
					rgba[1] += int64(coeff) * int64(g)
					rgba[2] += int64(coeff) * int64(b)
					rgba[3] += int64(coeff) * int64(a)
					sum += int64(coeff)
				}
			}
			offset := (y-newBounds.Min.Y)*out.Stride + (x-newBounds.Min.X)*8
			value := clampUint16(rgba[0] / sum)
			out.Pix[offset+0] = uint8(value >> 8)
			out.Pix[offset+1] = uint8(value)
			value = clampUint16(rgba[1] / sum)
			out.Pix[offset+2] = uint8(value >> 8)
			out.Pix[offset+3] = uint8(value)
			value = clampUint16(rgba[2] / sum)
			out.Pix[offset+4] = uint8(value >> 8)
			out.Pix[offset+5] = uint8(value)
			value = clampUint16(rgba[3] / sum)
			out.Pix[offset+6] = uint8(value >> 8)
			out.Pix[offset+7] = uint8(value)
		}
	}
}

func resizeRGBA64(in *image.RGBA64, out *image.RGBA64, coeffs []int32, offset []int, filterLength int) {
	newBounds := out.Bounds()
	maxX := in.Bounds().Dx() - 1
	for x := newBounds.Min.X; x < newBounds.Max.X; x++ {
		row := in.Pix[x*in.Stride:]
		for y := newBounds.Min.Y; y < newBounds.Max.Y; y++ {
			var rgba [4]int64
			var sum int64
			start := offset[y]
			ci := y * filterLength
			for i := 0; i < filterLength; i++ {
				coeff := coeffs[ci+i]
				if coeff != 0 {
					xi := start + i
					switch {
					case xi < 0:
						xi = 0
					case xi >= maxX:
						xi = maxX
					}
					rgba[0] += int64(coeff) * int64(uint16(row[xi*8+0])<<8|uint16(row[xi*8+1]))
					rgba[1] += int64(coeff) * int64(uint16(row[xi*8+2])<<8|uint16(row[xi*8+3]))
					rgba[2] += int64(coeff) * int64(uint16(row[xi*8+4])<<8|uint16(row[xi*8+5]))
					rgba[3] += int64(coeff) * int64(uint16(row[xi*8+6])<<8|uint16(row[xi*8+7]))
					sum += int64(coeff)
				}
			}
			xo := (y-newBounds.Min.Y)*out.Stride + (x-newBounds.Min.X)*8
			for k := 0; k < 4; k++ {
				value := clampUint16(rgba[k] / sum)
				out.Pix[xo+2*k] = uint8(value >> 8)
				out.Pix[xo+2*k+1] = uint8(value)
			}
		}
	}
}

const lanczosTaps = 6

// lanczosResize scales img to width x height.
func lanczosResize(img image.Image, width, height int) image.Image {
	scaleX := float64(img.Bounds().Dx()) / float64(width)
	scaleY := float64(img.Bounds().Dy()) / float64(height)
	switch input := img.(type) {
	case *image.RGBA:
		temp := image.NewRGBA(image.Rect(0, 0, input.Bounds().Dy(), width))
		result := image.NewRGBA(image.Rect(0, 0, width, height))
		coeffs, offset, fl := createWeights8(temp.Bounds().Dy(), lanczosTaps, scaleX)
		resizeRGBA(input, temp, coeffs, offset, fl)
		coeffs, offset, fl = createWeights8(result.Bounds().Dy(), lanczosTaps, scaleY)
		resizeRGBA(temp, result, coeffs, offset, fl)
		return result
	case *image.NRGBA:
		temp := image.NewRGBA(image.Rect(0, 0, input.Bounds().Dy(), width))
		result := image.NewRGBA(image.Rect(0, 0, width, height))
		coeffs, offset, fl := createWeights8(temp.Bounds().Dy(), lanczosTaps, scaleX)
		resizeNRGBA(input, temp, coeffs, offset, fl)
		coeffs, offset, fl = createWeights8(result.Bounds().Dy(), lanczosTaps, scaleY)
		resizeRGBA(temp, result, coeffs, offset, fl)
		return result
	case *image.YCbCr:
		temp := newYCC(image.Rect(0, 0, input.Bounds().Dy(), width))
		result := newYCC(image.Rect(0, 0, width, height))
		coeffs, offset, fl := createWeights8(temp.Rect.Dy(), lanczosTaps, scaleX)
		in := imageYCbCrToYCC(input)
		resizeYCbCr(in, temp, coeffs, offset, fl)
		coeffs, offset, fl = createWeights8(result.Rect.Dy(), lanczosTaps, scaleY)
		resizeYCbCr(temp, result, coeffs, offset, fl)
		return result.toYCbCr()
	case *image.Gray:
		temp := image.NewGray(image.Rect(0, 0, input.Bounds().Dy(), width))
		result := image.NewGray(image.Rect(0, 0, width, height))
		coeffs, offset, fl := createWeights8(temp.Bounds().Dy(), lanczosTaps, scaleX)
		resizeGray(input, temp, coeffs, offset, fl)
		coeffs, offset, fl = createWeights8(result.Bounds().Dy(), lanczosTaps, scaleY)
		resizeGray(temp, result, coeffs, offset, fl)
		return result
	case *image.RGBA64:
		temp := image.NewRGBA64(image.Rect(0, 0, input.Bounds().Dy(), width))
		result := image.NewRGBA64(image.Rect(0, 0, width, height))
		coeffs, offset, fl := createWeights16(temp.Bounds().Dy(), lanczosTaps, scaleX)
		resizeRGBA64(input, temp, coeffs, offset, fl)
		coeffs, offset, fl = createWeights16(result.Bounds().Dy(), lanczosTaps, scaleY)
		resizeRGBA64(temp, result, coeffs, offset, fl)
		return result
	default:
		temp := image.NewRGBA64(image.Rect(0, 0, input.Bounds().Dy(), width))
		result := image.NewRGBA64(image.Rect(0, 0, width, height))
		coeffs, offset, fl := createWeights16(temp.Bounds().Dy(), lanczosTaps, scaleX)
		resizeGeneric(input, temp, coeffs, offset, fl)
		coeffs, offset, fl = createWeights16(result.Bounds().Dy(), lanczosTaps, scaleY)
		resizeRGBA64(temp, result, coeffs, offset, fl)
		return result
	}
}
