package hl

import (
	"regexp"
	"strings"
)

// Emitter turns a regexp match into tokens.
type Emitter func(groups []string, l *Lexer) []Token

// Rule is a single lexer rule: a pattern tried at the current position, an
// emitter and an optional state mutation.
type Rule struct {
	Pattern string
	Type    TokenType
	Emit    Emitter
	Push    []string // states to push
	Pop     int      // number of states to pop
	Include string   // include another state's rules

	re        *regexp.Regexp
	lineStart bool
}

type Rules map[string][]Rule

// Lexer is a regexp state machine lexer.
type Lexer struct {
	Name      string
	Filenames []string
	Rules     Rules
	DotAll    bool
	compiled  bool
	resolved  map[string][]*Rule
	// analyse is an optional content based detector returning a score 0..1
	Analyse func(text string) float32
}

func (l *Lexer) compile() {
	if l.compiled {
		return
	}
	l.compiled = true
	l.resolved = map[string][]*Rule{}
	for state := range l.Rules {
		l.resolved[state] = l.resolveState(state, map[string]bool{})
	}
}

func (l *Lexer) resolveState(state string, seen map[string]bool) []*Rule {
	if seen[state] {
		return nil
	}
	seen[state] = true
	var out []*Rule
	for i := range l.Rules[state] {
		r := &l.Rules[state][i]
		if r.Include != "" {
			out = append(out, l.resolveState(r.Include, copySeen(seen))...)
			continue
		}
		if r.re == nil {
			pat := r.Pattern
			if strings.HasPrefix(pat, "^") {
				r.lineStart = true
				pat = pat[1:]
			}
			flags := "(?m)"
			if l.DotAll {
				flags = "(?ms)"
			}
			r.re = regexp.MustCompile(flags + `\A(?:` + pat + `)`)
		}
		out = append(out, r)
	}
	return out
}

func copySeen(m map[string]bool) map[string]bool {
	out := make(map[string]bool, len(m))
	for k, v := range m {
		out[k] = v
	}
	return out
}

// Tokenise lexes text starting in the "root" state.
func (l *Lexer) Tokenise(text string) []Token {
	return l.TokeniseState(text, "root")
}

func (l *Lexer) TokeniseState(text string, state string) []Token {
	l.compile()
	var tokens []Token
	stack := []string{state}
	pos := 0
	for pos < len(text) {
		cur := stack[len(stack)-1]
		rules := l.resolved[cur]
		matched := false
		for _, r := range rules {
			if r.lineStart && pos > 0 && text[pos-1] != '\n' {
				continue
			}
			loc := r.re.FindStringSubmatchIndex(text[pos:])
			if loc == nil {
				continue
			}
			end := loc[1]
			groups := make([]string, len(loc)/2)
			for i := range groups {
				if loc[2*i] >= 0 {
					groups[i] = text[pos+loc[2*i] : pos+loc[2*i+1]]
				}
			}
			if r.Emit != nil {
				tokens = append(tokens, r.Emit(groups, l)...)
			} else if end > 0 {
				tokens = append(tokens, Token{r.Type, groups[0]})
			}
			// state changes
			if r.Pop > 0 {
				for i := 0; i < r.Pop && len(stack) > 1; i++ {
					stack = stack[:len(stack)-1]
				}
			}
			for _, s := range r.Push {
				if s == "#push" {
					stack = append(stack, cur)
				} else {
					stack = append(stack, s)
				}
			}
			pos += end
			matched = true
			if end == 0 && len(r.Push) == 0 && r.Pop == 0 {
				// avoid infinite loops on empty matches without state change
				matched = false
			}
			break
		}
		if !matched {
			// emit one character as Error
			_, size := decodeRune(text[pos:])
			tokens = append(tokens, Token{Error, text[pos : pos+size]})
			pos += size
		}
	}
	return mergeAdjacent(tokens)
}

func decodeRune(s string) (rune, int) {
	for _, r := range s {
		return r, len(string(r))
	}
	return 0, 1
}

// mergeAdjacent joins consecutive tokens of the same type (as chroma's
// coalescing does for error tokens and some lexers). We only merge Error
// tokens to mimic chroma's behaviour.
func mergeAdjacent(tokens []Token) []Token {
	var out []Token
	for _, t := range tokens {
		if t.Value == "" {
			continue
		}
		if len(out) > 0 && out[len(out)-1].Type == Error && t.Type == Error {
			out[len(out)-1].Value += t.Value
			continue
		}
		out = append(out, t)
	}
	return out
}

// ---- emitter helpers ----

// ByGroups emits each capture group with the corresponding type. A nil
// entry in types means the group is lexed with the given sub-lexer state.
func ByGroups(types ...TokenType) Emitter {
	return func(groups []string, l *Lexer) []Token {
		var out []Token
		for i, t := range types {
			if i+1 >= len(groups) {
				break
			}
			if groups[i+1] == "" {
				continue
			}
			out = append(out, Token{t, groups[i+1]})
		}
		return out
	}
}

// GroupEmitter describes how one capture group is emitted.
type GroupEmitter struct {
	Type  TokenType
	Self  string // lex with this state of the same lexer
	Lexer *Lexer // lex with another lexer
	Fn    func(string) []Token
}

func ByGroupsEx(parts ...GroupEmitter) Emitter {
	return func(groups []string, l *Lexer) []Token {
		var out []Token
