			case p.Lexer != nil:
				out = append(out, p.Lexer.Tokenise(g)...)
			case p.Self != "":
				out = append(out, l.TokeniseState(g, p.Self)...)
			default:
				out = append(out, Token{p.Type, g})
			}
		}
		return out
	}
}

// Words builds an alternation pattern.
func Words(prefix, suffix string, words ...string) string {
	escaped := make([]string, len(words))
	for i, w := range words {
		escaped[i] = regexp.QuoteMeta(w)
	}
	return prefix + "(" + strings.Join(escaped, "|") + ")" + suffix
}

func Inc(state string) Rule { return Rule{Include: state} }
func R(pattern string, t TokenType) Rule {
	return Rule{Pattern: pattern, Type: t}
}
func RP(pattern string, t TokenType, push ...string) Rule {
	return Rule{Pattern: pattern, Type: t, Push: push}
