// Get returns a lexer by (lower case) name or alias.
func Get(name string) *Lexer {
	for _, l := range registry {
		if equalFold(l.Name, name) {
			return l
		}
		for _, a := range aliasesOf(l) {
			if equalFold(a, name) {
				return l
			}
		}
	}
	return nil
}

func aliasesOf(l *Lexer) []string {
	switch l {
	case Go:
		return []string{"go", "golang"}
	case JSON:
		return []string{"json"}
	case Markdown:
		return []string{"md", "mkd", "markdown"}
	case YAML:
		return []string{"yaml", "yml"}
	}
	return nil
}

func equalFold(a, b string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := 0; i < len(a); i++ {
		ca, cb := a[i], b[i]
		if ca >= 'A' && ca <= 'Z' {
			ca += 32
		}
		if cb >= 'A' && cb <= 'Z' {
			cb += 32
		}
		if ca != cb {
			return false
		}
	}
	return true
}
