func markdownCodeBlock(groups []string, l *Lexer) []Token {
	var out []Token
	out = append(out, Token{LiteralString, groups[1]})
	out = append(out, Token{LiteralString, groups[2]})
	out = append(out, Token{Text, groups[3]})
	code := groups[4]
	sub := Get(groups[2])
	if sub != nil {
		out = append(out, sub.Tokenise(code)...)
	} else {
		out = append(out, Token{Text, code})
	}
	out = append(out, Token{LiteralString, groups[5]})
	return out
}

