			RE(`([^"\n{]*)(:)( )`, ByGroups(NameTag, Punctuation, TextWhitespace)),
			RE(`([^"\n{]*)(:)(\n)`, ByGroups(NameTag, Punctuation, TextWhitespace)),
		},
