package hl

import (
	"path/filepath"
	"strings"
)

// Match returns the lexer for a filename, or nil.
func Match(filename string) *Lexer {
	base := filepath.Base(filename)
	for _, l := range registry {
		for _, pat := range l.Filenames {
			if ok, _ := filepath.Match(pat, base); ok {
				return l
			}
		}
	}
	return nil
}

// Analyse guesses a lexer from the content (shebang based), or nil.
func Analyse(text string) *Lexer {
	first := text
	if i := strings.IndexByte(text, '\n'); i >= 0 {
		first = text[:i]
	}
	if strings.HasPrefix(first, "#!") {
		for _, l := range registry {
			if l.Analyse != nil && l.Analyse(text) > 0 {
				return l
			}
		}
	}
	return nil
}

// Highlight returns the highlighted content for the given filename, or the
// content unchanged when no lexer applies.
func Highlight(filename, content string) string {
	l := Match(filename)
	if l == nil {
		l = Analyse(content)
	}
	if l == nil {
		return content
	}
	return Format(l.Tokenise(content))
}
