func cRules(extraKeywords []string, extraTypes string) Rules {
	kw := append(append([]string{}, cKeywords...), extraKeywords...)
	types := `(bool|int|long|float|short|double|char((8|16|32)_t)?|unsigned|signed|void|u?int(_fast|_least|)(8|16|32|64)_t` + extraTypes + `)\b`
	return Rules{
		"statements": {
			REP(`(L?)(")`, ByGroups(LiteralStringAffix, LiteralString), "string"),
			RE(`(L?)(')(\\.|\\[0-7]{1,3}|\\x[a-fA-F0-9]{1,2}|[^\\'\n])(')`, ByGroups(LiteralStringAffix, LiteralStringChar, LiteralStringChar, LiteralStringChar)),
			R(`(\d+\.\d*|\.\d+|\d+)[eE][+-]?\d+[LlUu]*`, LiteralNumberFloat),
			R(`(\d+\.\d*|\.\d+|\d+[fF])[fF]?`, LiteralNumberFloat),
			R(`0x[0-9a-fA-F]+[LlUu]*`, LiteralNumberHex),
			R(`0[0-7]+[LlUu]*`, LiteralNumberOct),
			R(`\d+[LlUu]*`, LiteralNumberInteger),
			R(`[~!%^&*+=|?:<>/-]`, Operator),
			R(`[()\[\],.]`, Punctuation),
			R(Words(``, `\b`, kw...), Keyword),
			R(types, KeywordType),
			R(Words(``, `\b`, "inline", "_inline", "__inline", "naked", "restrict", "thread", "typename"), KeywordReserved),
			R(`(__m(128i|128d|128|64))\b`, KeywordReserved),
			R(Words(`__`, `\b`, "asm", "int8", "based", "except", "int16", "stdcall", "cdecl", "fastcall", "int32", "declspec", "finally", "int64", "try", "leave", "wchar_t", "w64", "unaligned", "raise", "noop", "identifier", "forceinline", "assume"), KeywordReserved),
			R(`(true|false|NULL)\b`, NameBuiltin),
			{Pattern: `([a-zA-Z_]\w*)(\s*)(:)`, Emit: ByGroups(NameLabel, Text, Punctuation), NLA: `:`},
			RE(`([a-zA-Z_]\w*)(\s*)(\()`, ByGroups(NameFunction, Text, Punctuation)),
			R(`[a-zA-Z_]\w*`, Name),
		},
		"root": {
			Inc("whitespace"),
			REP(`((?:[\w*\s])+?(?:\s|[*]))([a-zA-Z_]\w*)(\s*\([^;]*?\))([^;{]*)(\{)`, ByGroupsEx(GroupEmitter{Self: "root"}, GroupEmitter{Type: NameFunction}, GroupEmitter{Self: "root"}, GroupEmitter{Self: "root"}, GroupEmitter{Type: Punctuation}), "function"),
			RE(`((?:[\w*\s])+?(?:\s|[*]))([a-zA-Z_]\w*)(\s*\([^;]*?\))([^;]*)(;)`, ByGroupsEx(GroupEmitter{Self: "root"}, GroupEmitter{Type: NameFunction}, GroupEmitter{Self: "root"}, GroupEmitter{Self: "root"}, GroupEmitter{Type: Punctuation})),
			RP(``, Text, "statement"),
		},
		"statement": {
			Inc("whitespace"),
			Inc("statements"),
			R(`[{}]`, Punctuation),
			RPop(`;`, Punctuation, 1),
		},
		"function": {
			Inc("whitespace"),
			Inc("statements"),
			R(`;`, Punctuation),
			RP(`\{`, Punctuation, "#push"),
			RPop(`\}`, Punctuation, 1),
		},
		"string": {
			RPop(`"`, LiteralString, 1),
			R(`\\([\\abfnrtv"']|x[a-fA-F0-9]{2,4}|u[a-fA-F0-9]{4}|U[a-fA-F0-9]{8}|[0-7]{1,3})`, LiteralStringEscape),
			R(`[^\\"\n]+`, LiteralString),
			R(`\\\n`, LiteralString),
			R(`\\`, LiteralString),
		},
		"macro": {
			RE(`(include)(\s*(?:/[*].*?[*]/\s*)?)([^\n]+)`, ByGroups(CommentPreproc, Text, CommentPreprocFile)),
			R(`[^/\n]+`, CommentPreproc),
			R(`/[*](.|\n)*?[*]/`, CommentMultiline),
			RPop(`//.*?\n`, CommentSingle, 1),
			R(`/`, CommentPreproc),
			RPop(`\n`, CommentPreproc, 1),
		},
		"if0": {
			RP(`^\s*#if.*?(?:\n|$)`, CommentPreproc, "#push"),
			RPop(`^\s*#el(?:se|if).*\n`, CommentPreproc, 1),
			RPop(`^\s*#endif.*?(?:\n|$)`, CommentPreproc, 1),
			R(`.*?\n`, Comment),
		},
		"whitespace": {
			RP(`^#if\s+0`, CommentPreproc, "if0"),
			RP(`^#`, CommentPreproc, "macro"),
			REP(`^(\s*(?:/[*].*?[*]/\s*)?)(#if\s+0)`, ByGroupsEx(GroupEmitter{Self: "root"}, GroupEmitter{Type: CommentPreproc}), "if0"),
			REP(`^(\s*(?:/[*].*?[*]/\s*)?)(#)`, ByGroupsEx(GroupEmitter{Self: "root"}, GroupEmitter{Type: CommentPreproc}), "macro"),
			R(`\n`, Text),
			R(`\s+`, Text),
			R(`\\\n`, Text),
			R(`//(\n|(.|\n)*?[^\\]\n)`, CommentSingle),
			R(`/(\\\n)?[*](.|\n)*?[*](\\\n)?/`, CommentMultiline),
		},
	}
}

