var jsKeywords = []string{"for", "in", "of", "while", "do", "break", "return", "continue", "switch", "case", "default", "if", "else", "throw", "try", "catch", "finally", "new", "delete", "typeof", "instanceof", "void", "yield", "await", "async", "this", "import", "export", "from", "as", "debugger", "with"}

func jsRules(extraDecl string, extraTypes []string) Rules {
	decl := `(var|let|with|function|class|const|extends|static|get|set` + extraDecl + `)\b`
	root := []Rule{
		RP(`\A#! ?/.*?\n`, CommentHashbang, ""),
		R(`^(?=\s|/|<!--)`, Text),
		Inc("commentsandwhitespace"),
		REP(`(?:\+\+|--|~|&&|\?|:|\|\||\\(?=\n)|(<<|>>>?|==?|!=?|[-<>+*%&|^/])=?)`, ByGroups(Operator), "slashstartsregex"),
		RP(`[{(\[;,]`, Punctuation, "slashstartsregex"),
		R(`[})\].]`, Punctuation),
		REP(`(for|in|of|while|do|break|return|continue|switch|case|default|if|else|throw|try|catch|finally|new|delete|typeof|instanceof|void|yield|await|async|this|import|export|from|as|debugger|with)\b`, ByGroups(Keyword), "slashstartsregex"),
		R(decl, KeywordDeclaration),
		R(`(abstract|boolean|byte|char|double|enum|final|float|goto|implements|int|interface|long|native|package|private|protected|public|short|synchronized|throws|transient|volatile)\b`, KeywordReserved),
		R(`(true|false|null|NaN|Infinity|undefined)\b`, KeywordConstant),
		R(`(Array|Boolean|Date|Error|Function|Math|Number|Object|Packages|RegExp|String|decodeURI|decodeURIComponent|encodeURI|encodeURIComponent|Error|eval|isFinite|isNaN|isSafeInteger|parseFloat|parseInt|document|this|window|globalThis|Symbol)\b`, NameBuiltin),
		R(`(?:[$_\p{L}\p{N}]|\\u[a-fA-F0-9]{4})(?:(?:[$\p{L}\p{N}]|\\u[a-fA-F0-9]{4}))*`, NameOther),
		R(`[0-9](_?[0-9])*\.[0-9](_?[0-9])*([eE][-+]?[0-9](_?[0-9])*)?`, LiteralNumberFloat),
		R(`0[bB][01](_?[01])*`, LiteralNumberBin),
		R(`0[oO]?[0-7](_?[0-7])*`, LiteralNumberOct),
		R(`0[xX][0-9a-fA-F](_?[0-9a-fA-F])*`, LiteralNumberHex),
		R(`[0-9](_?[0-9])*n?`, LiteralNumberInteger),
		R(`"(\\\\|\\"|[^"])*"`, LiteralStringDouble),
		R(`'(\\\\|\\'|[^'])*'`, LiteralStringSingle),
		RP("`", LiteralStringBacktick, "interp"),
	}
	if len(extraTypes) > 0 {
		root = append(root[:9], append([]Rule{R(Words(``, `\b`, extraTypes...), KeywordType)}, root[9:]...)...)
	}
	return Rules{
		"commentsandwhitespace": {
			R(`\s+`, Text),
			R(`<!--`, Comment),
			R(`//.*?\n`, CommentSingle),
			R(`/\*.*?\*/`, CommentMultiline),
		},
		"slashstartsregex": {
			Inc("commentsandwhitespace"),
			REPop(`(/(\\.|[^[/\\\n]|\[(\\.|[^\]\\\n])*])+/([gimuysd]+\b|\B))`, ByGroups(LiteralStringRegex), 1),
			{Pattern: `(?=/)`, Emit: ByGroups(), Pop: 1, LA: `/`},
			RPop(``, Text, 1),
		},
		"badregex": {RPop(`\n`, Text, 1)},
		"root": root,
		"interp": {
			RPop("`", LiteralStringBacktick, 1),
			R(`\\\\`, LiteralStringBacktick),
			R("\\\\`", LiteralStringBacktick),
			R(`\\[^`\\]`, LiteralStringBacktick),
			RP(`\$\{`, LiteralStringInterpol, "interp-inside"),
			R(`\$`, LiteralStringBacktick),
			R("[^`\\\\$]+", LiteralStringBacktick),
		},
		"interp-inside": {
			RPop(`\}`, LiteralStringInterpol, 1),
			Inc("root"),
		},
	}
}

